// The three questions the k8ssandra view answers, cycled with `g` off a single fetch: is the ring
// healthy (Cluster), is anything restorable (Backups), and what maintenance is running or has run
// (Ops). Backups is where the view earns its keep, so `:medusa` opens straight on it.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum K8cWorld {
    Cluster,
    Backups,
    Ops,
}

// One visual row of the k8ssandra view, index-aligned with `App::snapshot` like every other tree
// view here. The records that carry hint vectors are boxed: this vector holds one line per visible
// row, and a datacenter is several times the size of a task row.
#[derive(Debug, Clone)]
enum K8cRow {
    Cluster(Box<K8cCluster>),
    Datacenter(Box<K8cDatacenter>),
    Node(Box<K8cNode>),
    Schedule(Box<MedSchedule>),
    Job(Box<MedJob>),
    Backup(Box<MedBackup>),
    Restore(Box<MedRestore>),
    Task(Box<MedTask>),
    CassTask(Box<CassTask>),
    // A `nodetool` Job kdt started: a Job, not a CRD, and the only row here whose object this view
    // wrote from scratch.
    Nodetool(Box<NtJob>),
    Reaper(Box<ReaperRec>),
    // Parent rows for what hangs off no schedule: the Medusa catalogue itself, the runs whose
    // schedule is gone, and the restores. They group, they are not objects.
    Group { key: &'static str, namespace: String, label: String, count: usize },
}

impl K8cRow {
    fn hints(&self) -> &[crate::storage::Hint] {
        match self {
            K8cRow::Cluster(c) => &c.hints,
            K8cRow::Datacenter(d) => &d.hints,
            K8cRow::Node(n) => &n.hints,
            K8cRow::Schedule(s) => &s.hints,
            K8cRow::Job(j) => &j.hints,
            K8cRow::Backup(b) => &b.hints,
            K8cRow::Restore(r) => &r.hints,
            K8cRow::Task(t) => &t.hints,
            K8cRow::CassTask(t) => &t.hints,
            K8cRow::Nodetool(j) => &j.hints,
            K8cRow::Reaper(r) => &r.hints,
            K8cRow::Group { .. } => &[],
        }
    }

    fn uid(&self) -> String {
        match self {
            K8cRow::Cluster(c) => c.uid.clone(),
            K8cRow::Datacenter(d) => d.uid.clone(),
            K8cRow::Node(n) => n.uid.clone(),
            K8cRow::Schedule(s) => s.uid.clone(),
            K8cRow::Job(j) => j.uid.clone(),
            K8cRow::Backup(b) => b.uid.clone(),
            K8cRow::Restore(r) => r.uid.clone(),
            K8cRow::Task(t) => t.uid.clone(),
            K8cRow::CassTask(t) => t.uid.clone(),
            K8cRow::Nodetool(j) => j.uid.clone(),
            K8cRow::Reaper(r) => r.uid.clone(),
            K8cRow::Group { key, namespace, .. } => format!("k8c|group|{namespace}|{key}"),
        }
    }

    fn namespace(&self) -> &str {
        match self {
            K8cRow::Cluster(c) => &c.namespace,
            K8cRow::Datacenter(d) => &d.namespace,
            K8cRow::Node(n) => &n.namespace,
            K8cRow::Schedule(s) => &s.namespace,
            K8cRow::Job(j) => &j.namespace,
            K8cRow::Backup(b) => &b.namespace,
            K8cRow::Restore(r) => &r.namespace,
            K8cRow::Task(t) => &t.namespace,
            K8cRow::CassTask(t) => &t.namespace,
            K8cRow::Nodetool(j) => &j.namespace,
            K8cRow::Reaper(r) => &r.namespace,
            K8cRow::Group { namespace, .. } => namespace,
        }
    }

    // The fold key of a row that has children, `None` for a leaf.
    fn fold_key(&self) -> Option<String> {
        match self {
            K8cRow::Cluster(_) | K8cRow::Datacenter(_) | K8cRow::Schedule(_)
            | K8cRow::Group { .. } => Some(self.uid()),
            _ => None,
        }
    }

}

// The three ways to look at reflector's work (`g`). Sources is the tree everything hangs from;
// Mirrors flattens the copies so one can scan versions side by side; Orphans isolates the copies no
// source claims any more, which is where the surprises live.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReflWorld {
    Sources,
    Mirrors,
    Orphans,
}

// How the reflector view is filtered (`f`): everything, or only what needs a human.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum ReflFilter {
    All,
    Problems,
}

impl ReflFilter {
    fn label(self) -> &'static str {
        match self {
            ReflFilter::All => "ALL",
            ReflFilter::Problems => "PROBLEMS",
        }
    }
}

// One visual row of the reflector view, index-aligned with `App::snapshot` like every other tree
// view here. `Target` carries its source's index so the detail panel can show both sides of the
// pair without looking anything up.
#[derive(Debug, Clone)]
enum ReflRow {
    Source { idx: usize, collapsed: bool },
    Target { src: usize, target: usize },
    Orphan { idx: usize },
}

// The two object worlds the storage view toggles between (`g`): claims — what a workload asked for
// and whether it got it — and volumes, grouped under the class that provisions them.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StoWorld {
    Claims,
    Volumes,
}

// One visual row of the storage view. Kept index-aligned with the snapshot so the detail panel and
// the generic object machinery (`y`, `Ctrl-D`, Related) track the selection.
#[derive(Debug, Clone)]
enum StoRow {
    Claim(PvcResource),
    Volume(PvResource),
    Class(ScResource),
}

impl StoRow {
    // The row's diagnosis, used both by the detail panel and by the `f` filter.
    fn hints(&self) -> &[crate::storage::Hint] {
        match self {
            StoRow::Claim(c) => &c.hints,
            StoRow::Volume(v) => &v.hints,
            StoRow::Class(c) => &c.hints,
        }
    }

    // Worth a human's attention: an Info hint is context ("this class does not expand"), a Warn or
    // Danger one is something that is, or is about to be, a problem.
    fn has_problem(&self) -> bool {
        self.hints().iter().any(|h| h.level >= StoHintLevel::Warn)
    }
}

// How the storage view is filtered (`f`): everything, or only the rows carrying a real problem.
// The capacity view reuses it: the question — "show me only what is actually wrong" — is the same.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StoFilter { All, Problems }

// The three questions of the capacity view, cycled with `g` off a single fetch: what each node has
// left (and what its loss would cost), how the workloads are sized, and which quota is about to
// refuse the next deployment.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum CapWorld {
    Nodes,
    Workloads,
    Quotas,
}

// One visual row of the capacity view, index-aligned with the snapshot like every other view.
#[derive(Debug, Clone)]
enum CapRow {
    Node(Box<NodeRoom>),
    Workload(WorkloadSizing),
    Quota(QuotaPressure),
}

impl CapRow {
    fn hints(&self) -> &[crate::storage::Hint] {
        match self {
            CapRow::Node(n) => &n.hints,
            CapRow::Workload(w) => &w.hints,
            CapRow::Quota(q) => &q.hints,
        }
    }

    fn has_problem(&self) -> bool {
        self.hints().iter().any(|h| h.level >= StoHintLevel::Warn)
    }
}

impl StoFilter {
    fn label(self) -> &'static str {
        match self { StoFilter::All => "ALL", StoFilter::Problems => "PROBLEMS" }
    }
}
