// Detail panel (split top): the selected Namespace's phase, origin and age, then its labels and
// annotations. The object is cluster-scoped, so there is no namespace/name pair — just the name.
fn draw_namespaces_detail(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    let Some(ns) = app.namespace_selected() else {
        let p = Paragraph::new(Line::from(Span::styled(
            lang::t(app.ai_language).ns_empty_select, Style::default().fg(DIM),
        )))
        .block(Block::default().borders(Borders::ALL).title(" namespaces "));
        f.render_widget(p, area);
        return;
    };

    let (title, mut lines) = namespace_detail_lines(&ns);

    let visible = area.height.saturating_sub(2) as usize;
    let max_scroll = lines.len().saturating_sub(visible);
    if app.namespaces_detail_scroll > max_scroll {
        app.namespaces_detail_scroll = max_scroll;
    }
    app.namespaces_detail_scroll = text_search_top(app, Mode::Namespaces, &mut lines, visible, app.namespaces_detail_scroll, max_scroll);
    let p = Paragraph::new(lines)
        .scroll((app.namespaces_detail_scroll as u16, app.namespaces_h_scroll as u16))
        .block(Block::default().borders(Borders::ALL).title(title));
    f.render_widget(p, area);
}

fn namespace_detail_lines(ns: &NamespaceInfo) -> (Line<'static>, Vec<Line<'static>>) {
    let st = lang::active();
    let title = Line::from(Span::styled(
        format!(" {} ", ns.name),
        Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD),
    ));

    let label = |k: &str, v: String| {
        Line::from(vec![
            Span::styled(format!("{k:<12}"), Style::default().fg(DIM)),
            Span::raw(v),
        ])
    };
    let mut lines: Vec<Line<'static>> = vec![
        label(st.lbl_phase, ns.phase.clone()),
        label(st.lbl_origin, ns.provenance.label()),
        label(st.lbl_age, ns.age.clone()),
    ];

    let section = |lines: &mut Vec<Line<'static>>, header: &str, kv: &[(String, String)]| {
        if kv.is_empty() { return; }
        lines.push(Line::from(""));
        lines.push(Line::from(Span::styled(
            header.to_string(),
            Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
        )));
        for (k, v) in kv {
            lines.push(Line::from(vec![
                Span::styled(format!("  {k}="), Style::default().fg(Color::Cyan)),
                Span::raw(v.clone()),
            ]));
        }
    };
    section(&mut lines, st.lbl_labels, &ns.labels);
    section(&mut lines, st.lbl_annotations, &ns.annotations);

    (title, lines)
}

fn draw_flux_table(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    let (resources, loading, error, counts) = {
        let s = app.flux_state.lock().expect("flux poisoned");
        (s.resources.clone(), s.loading, s.error.clone(), s.counts())
    };

    let (ready, failed, unknown, suspended, reconciling) = counts;
    let title = if let Some(e) = &error {
        format!("flux (erreur: {})", e)
    } else if loading && resources.is_empty() {
        "flux (chargement...)".to_string()
    } else {
        format!(
            "flux ({} · ✓{} ✗{} ↻{} ?{} ■{})",
            resources.len(), ready, failed, reconciling, unknown, suspended
        )
    };

    let header_row = flux_header_row();
    let selected = app.table_state.selected();
    let (rows, widths, msg_scroll) =
        flux_table_parts(&resources, selected, app.msg_scroll, area.width);
    app.msg_scroll = msg_scroll;

    let table = Table::new(rows, widths)
        .header(header_row)
        .block(Block::default().borders(Borders::ALL).title(title))
        .row_highlight_style(Style::default().bg(SELECTED_BG).add_modifier(Modifier::BOLD))
        .highlight_symbol("> ");

    f.render_stateful_widget(table, area, &mut app.table_state);
}

fn flux_header_row() -> Row<'static> {
    Row::new(vec![
        Cell::from("KIND"), Cell::from("NAMESPACE"), Cell::from("NAME"),
        Cell::from("READY"), Cell::from("REVISION"), Cell::from("AGE"), Cell::from("MESSAGE"),
    ])
    .style(Style::default().fg(Color::Black).bg(Color::DarkGray).add_modifier(Modifier::BOLD))
}

// Rows and column widths of the flat Flux table, plus the message offset clamped to what the
// focused row can actually show. Split out of the draw so the layout can be rendered — and its
// right border checked — without a cluster behind it.
fn flux_table_parts(
    resources: &[FluxResource],
    selected: Option<usize>,
    msg_scroll: usize,
    area_width: u16,
) -> (Vec<Row<'static>>, Vec<Constraint>, usize) {
    let kind_w = col_width(resources.iter().map(|r| r.kind.as_str()), "KIND", 8, 20);
    let ns_w = col_width(resources.iter().map(|r| r.namespace.as_str()), "NAMESPACE", 9, 24);
    let name_w = col_width(resources.iter().map(|r| r.name.as_str()), "NAME", 12, 50);
    // Those three size themselves on the data and together can ask for 94 cells, which overruns a
    // narrow terminal before the message column is even reached — ratatui then truncates whatever
    // comes last and the row runs into the right border. So NAME, the most elastic of them, gives
    // back whatever is needed to leave the message column a usable width.
    const MSG_MIN: u16 = 24;
    let others = kind_w + ns_w + 10 + 20 + 6 + HIGHLIGHT_W + 1 + 6;
    let budget = area_width.saturating_sub(2).saturating_sub(others);
    let name_w = name_w.min(budget.saturating_sub(MSG_MIN)).max(12);
    // Seven columns, so six inter-column gaps — plus the two cells `highlight_symbol("> ")` takes
    // off every row, which the focused row's message would otherwise spend running into the right
    // border. The trailing +1 keeps the longest line off that border.
    let msg_w = flux_msg_width(area_width, kind_w + ns_w + name_w + 10 + 20 + 6 + HIGHLIGHT_W + 1, 7);
    // Clamped here rather than in the key handler: this is where both the column width and the text
    // under the cursor are known, so ← comes straight back instead of walking off an offset that
    // was never displayed.
    let msg_scroll = msg_scroll.min(
        selected
            .and_then(|i| resources.get(i))
            .map(|r| msg_max_offset(flux_message_len(r), msg_w))
            .unwrap_or(0),
    );

    let rows: Vec<Row> = resources.iter().enumerate().map(|(i, r)| {
        let (ready_txt, ready_color) = if r.suspended {
            ("Suspended", Color::Yellow)
        } else {
            match r.ready {
                FluxReady::Ready => ("Ready", Color::Green),
                FluxReady::Reconciling => ("Reconciling", Color::Cyan),
                FluxReady::Failed => ("Failed", Color::Red),
                FluxReady::Unknown => ("Unknown", Color::Yellow),
                FluxReady::NotApplicable => ("N/A", DIM),
            }
        };
        let row_style = match (r.suspended, r.ready) {
            (false, FluxReady::Failed) => Style::default().fg(Color::White).bg(Color::Rgb(40, 0, 0)),
            (false, FluxReady::Unknown) => Style::default().fg(Color::Yellow),
            (false, FluxReady::Reconciling) => Style::default().fg(Color::Cyan),
            (true, _) => Style::default().fg(DIM),
            (false, FluxReady::Ready) => Style::default(),
            (false, FluxReady::NotApplicable) => Style::default(),
        };
        let msg_color = if r.ready == FluxReady::Failed && !r.suspended { Color::Red } else { DIM };
        // The focused row pans its message with ←/→; every row stays one line high. It goes through
        // the window even at offset 0, so the trailing `…` says there is something to pan to.
        let msg_cell = if selected == Some(i) {
            Cell::from(line_window(&flux_message_line(r, msg_color), msg_scroll, msg_w))
        } else {
            flux_message_cell(r, msg_color)
        };
        Row::new(vec![
            Cell::from(r.kind.clone()).style(Style::default().fg(Color::Cyan)),
            Cell::from(r.namespace.clone()),
            Cell::from(r.name.clone()).style(Style::default().add_modifier(Modifier::BOLD)),
            Cell::from(ready_txt).style(Style::default().fg(ready_color).add_modifier(Modifier::BOLD)),
            Cell::from(r.revision.clone()).style(Style::default().fg(DIM)),
            Cell::from(r.age.clone()).style(Style::default().fg(DIM)),
            msg_cell,
        ])
        .style(row_style)
    }).collect();

    // Pinned rather than `Min`, for the same reason as the tree below: a `Min` last column swallows
    // the margin that was reserved for it and the message lands on the right border.
    let widths = vec![
        Constraint::Length(kind_w), Constraint::Length(ns_w), Constraint::Length(name_w),
        Constraint::Length(10), Constraint::Length(20), Constraint::Length(6),
        Constraint::Length(msg_w as u16),
    ];

    (rows, widths, msg_scroll)
}

// Renders the Flux dependency tree (source → workload → dependent workloads) with indentation and
// collapse markers, reusing the same status colouring as the flat table.
fn draw_flux_tree(f: &mut ratatui::Frame, app: &mut App, area: Rect) {
    let (resources, error) = {
        let s = app.flux_state.lock().expect("flux poisoned");
        (s.resources.clone(), s.error.clone())
    };

    let st = lang::t(app.ai_language);
    let title = if let Some(e) = &error {
        lang::fill(st.ui_title_error, &[("view", st.flux_tree_view), ("e", e)])
    } else {
        lang::fill(
            st.flux_tree_title,
            &[("n", &app.flux_tree_view.len().to_string())],
        )
    };

    let selected = app.table_state.selected();
    let (rows, widths, msg_scroll) = flux_tree_table_parts(
        &app.flux_tree_view,
        &resources,
        &app.flux_inv_expanded,
        selected,
        app.msg_scroll,
        area.width,
    );
    app.msg_scroll = msg_scroll;

    let table = Table::new(rows, widths)
        .header(flux_tree_header_row())
        .block(Block::default().borders(Borders::ALL).title(title))
        .row_highlight_style(Style::default().bg(SELECTED_BG).add_modifier(Modifier::BOLD))
        .highlight_symbol("> ");

    f.render_stateful_widget(table, area, &mut app.table_state);
}

fn flux_tree_header_row() -> Row<'static> {
    Row::new(vec![
        Cell::from("RESOURCE"), Cell::from("READY"), Cell::from("REVISION"),
        Cell::from("AGE"), Cell::from("MESSAGE"),
    ])
    .style(Style::default().fg(Color::Black).bg(Color::DarkGray).add_modifier(Modifier::BOLD))
}

// Rows and column widths of the Flux tree, plus the message offset clamped to what the focused row
// can show. Split out of the draw for the same reason as the flat table: the layout is rendered and
// its right border checked without a cluster behind it.
fn flux_tree_table_parts(
    view: &[TreeRow],
    resources: &[FluxResource],
    inv_expanded: &std::collections::HashMap<String, (String, String, String, String)>,
    selected: Option<usize>,
    msg_scroll: usize,
    area_width: u16,
) -> (Vec<Row<'static>>, Vec<Constraint>, usize) {
    // First pass: build every (indented) label so the RESOURCE column can be sized before the rows
    // are constructed — the MESSAGE width (needed to wrap the focused row) depends on that column.
    let labels: Vec<String> = view
        .iter()
        .map(|row| match row {
            TreeRow::Res(n) => {
                let Some(r) = resources.get(n.idx) else { return String::new(); };
                let marker = if n.has_children {
                    if n.collapsed { "▸" } else { "▾" }
                } else {
                    " "
                };
                let mut label = format!("{}{} {} {}", "  ".repeat(n.depth), marker, r.kind, r.name);
                // Show that a Kustomization can reveal (or hide) its applied objects with +/-.
                if r.kind == "Kustomization" {
                    let expanded = inv_expanded.contains_key(&flux_tree_uid(r));
                    label.push_str(if expanded { "  ⊟" } else { "  ⊞" });
                }
                label.push_str(&hidden_badge(n));
                label
            }
            TreeRow::Inv { depth, item, .. } => {
                let nsname = if item.namespace.is_empty() {
                    item.name.clone()
                } else {
                    format!("{}/{}", item.namespace, item.name)
                };
                format!("{}{} {} {}", "  ".repeat(*depth), inventory_glyph(item).0, item.kind, nsname)
            }
        })
        .collect();
    let name_w = labels
        .iter()
        .map(|l| l.chars().count())
        .max()
        .unwrap_or(0)
        .max("RESOURCE".chars().count());
    let name_col = (name_w as u16).clamp(24, 80);
    // Five columns, four gaps, plus `highlight_symbol("> ")` and the one-cell margin — same reason
    // as the flat table above.
    let msg_w = flux_msg_width(area_width, name_col + 10 + 18 + 6 + HIGHLIGHT_W + 1, 5);
    // Same clamp as the flat table. An inventory leaf has no message of its own, so the pan simply
    // has nowhere to go there.
    let msg_scroll = msg_scroll.min(
        selected
            .and_then(|i| view.get(i))
            .and_then(|row| match row {
                TreeRow::Res(n) => resources.get(n.idx),
                TreeRow::Inv { .. } => None,
            })
            .map(|r| msg_max_offset(flux_message_len(r), msg_w))
            .unwrap_or(0),
    );

    let mut emit_idx = 0usize;
    let rows: Vec<Row> = view
        .iter()
        .enumerate()
        .filter_map(|(vi, row)| {
            let this_idx = emit_idx;
            let label = labels[vi].clone();
            let built = match row {
                TreeRow::Res(n) => {
                    let r = resources.get(n.idx)?;
                    let (ready_txt, ready_color) = if r.suspended {
                        ("Suspended", Color::Yellow)
                    } else {
                        match r.ready {
                            FluxReady::Ready => ("Ready", Color::Green),
                            FluxReady::Reconciling => ("Reconciling", Color::Cyan),
                            FluxReady::Failed => ("Failed", Color::Red),
                            FluxReady::Unknown => ("Unknown", Color::Yellow),
                            FluxReady::NotApplicable => ("N/A", DIM),
                        }
                    };
                    let row_style = match (r.suspended, r.ready) {
                        (false, FluxReady::Failed) => Style::default().fg(Color::White).bg(Color::Rgb(40, 0, 0)),
                        (false, FluxReady::Unknown) => Style::default().fg(Color::Yellow),
                        (false, FluxReady::Reconciling) => Style::default().fg(Color::Cyan),
                        (true, _) => Style::default().fg(DIM),
                        (false, FluxReady::Ready) => Style::default(),
                        (false, FluxReady::NotApplicable) => Style::default(),
                    };
                    let msg_color = if r.ready == FluxReady::Failed && !r.suspended { Color::Red } else { DIM };
                    // The focused row pans its message with ←/→ and stays one line high.
                    let msg_cell = if selected == Some(this_idx) {
                        Cell::from(line_window(&flux_message_line(r, msg_color), msg_scroll, msg_w))
                    } else {
                        flux_message_cell(r, msg_color)
                    };
                    Row::new(vec![
                        Cell::from(labelled_row(&label, n)),
                        Cell::from(ready_txt).style(Style::default().fg(ready_color).add_modifier(Modifier::BOLD)),
                        Cell::from(r.revision.clone()).style(Style::default().fg(DIM)),
                        Cell::from(r.age.clone()).style(Style::default().fg(DIM)),
                        msg_cell,
                    ])
                    .style(row_style)
                }
                TreeRow::Inv { item, .. } => {
                    let (_, color) = inventory_glyph(item);
                    let ready_txt = if item.reconciling {
                        "Reconciling"
                    } else {
                        match item.ready {
                            Some(true) => "Ready",
                            Some(false) => "NotReady",
                            None => "—",
                        }
                    };
                    Row::new(vec![
                        Cell::from(label).style(Style::default().fg(color)),
                        Cell::from(ready_txt).style(Style::default().fg(color)),
                        Cell::from(""),
                        Cell::from(""),
                        Cell::from(item.msg.clone()).style(Style::default().fg(DIM)),
                    ])
                }
            };
            emit_idx += 1;
            Some(built)
        })
        .collect();

    // The message column is pinned to the width its text was windowed at, not left as `Min`: a
    // `Min` column expands over every cell that is left, the reserved margin included, so the text
    // ends up flush against the right border however carefully `msg_w` was computed.
    let widths = vec![
        Constraint::Length(name_col), Constraint::Length(10), Constraint::Length(18),
        Constraint::Length(6), Constraint::Length(msg_w as u16),
    ];

    (rows, widths, msg_scroll)
}

// What a folded branch hides, appended to its label: a fold that says nothing about its contents is
// what turns "where is the error" into a walk down the whole tree. Only the two states worth acting
// on are counted — a folded branch full of Ready resources has nothing to announce.
fn hidden_badge(n: &FlatTreeNode) -> String {
    let mut badge = String::new();
    if n.hidden_failed > 0 {
        badge.push_str(&format!("  ✗{}", n.hidden_failed));
    }
    if n.hidden_reconciling > 0 {
        badge.push_str(&format!("  ↻{}", n.hidden_reconciling));
    }
    badge
}

// The label of a resource row, with the hidden-problem badge coloured apart from the rest: red for a
// failure buried under the fold, cyan for a reconcile in flight — the same colours the rows
// themselves use, so the badge reads as "that state, down there".
fn labelled_row(label: &str, n: &FlatTreeNode) -> Line<'static> {
    let badge = hidden_badge(n);
    if badge.is_empty() {
        return Line::from(label.to_string());
    }
    let plain = label.len() - badge.len();
    let colour = if n.hidden_failed > 0 { Color::Red } else { Color::Cyan };
    Line::from(vec![
        Span::raw(label[..plain].to_string()),
        Span::styled(
            badge,
            Style::default().fg(colour).add_modifier(Modifier::BOLD),
        ),
    ])
}

// Badge prefixed to the message of a Kustomization that does not prune (spec.prune = false): what it
// applied outlives its removal from git. Pruning is the Flux default and what a GitOps reader
// assumes, so it is the absence that is worth marking, not the presence — and a Kustomization set to
// keep its objects is a deliberate state, not a fault, hence a neutral badge and not a warning.
const NO_PRUNE_BADGE: &str = "⊡ no-prune ";

// Empty for the kinds that have no spec.prune at all (everything but Kustomization) as well as for
// the pruning ones: only `false` says something the message does not already say.
fn prune_badge(prune: Option<bool>) -> &'static str {
    if prune == Some(false) { NO_PRUNE_BADGE } else { "" }
}

fn no_prune_badge_style() -> Style {
    Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
}

// Message of a Flux row, prefixed with the no-prune badge when the Kustomization keeps objects
// removed from git.
fn flux_message_line(r: &FluxResource, msg_color: Color) -> Line<'static> {
    let badge = prune_badge(r.prune);
    let mut spans = Vec::with_capacity(2);
    if !badge.is_empty() {
        spans.push(Span::styled(badge, no_prune_badge_style()));
    }
    spans.push(Span::styled(r.message.clone(), Style::default().fg(msg_color)));
    Line::from(spans)
}

fn flux_message_cell(r: &FluxResource, msg_color: Color) -> Cell<'static> {
    Cell::from(flux_message_line(r, msg_color))
}

// Character length of what the MESSAGE cell of a Flux row holds, badge included — the quantity the
// pan offset is bounded by.
fn flux_message_len(r: &FluxResource) -> usize {
    prune_badge(r.prune).chars().count() + r.message.chars().count()
}

// Footer label for `z`: the key toggles, so it has to name what it would do to the row under the
// cursor — on an already suspended resource it resumes. The reading comes from the snapshot, the
// same state the table shows; the patch itself still decides its direction from the live object.
fn suspend_key_label(sel: Option<&EventRecord>, st: &'static lang::Strings) -> &'static str {
    if sel.is_some_and(|r| r.reason == "Suspended") { st.k_resume } else { st.k_suspend }
}

// Word-wrap to `width` columns, hard-breaking tokens longer than the width (Flux failure messages
// carry long unbreakable tokens like fully-qualified CRD names).
fn wrap_words(text: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let mut lines: Vec<String> = Vec::new();
    let mut cur = String::new();
    for word in text.split_whitespace() {
        let mut word = word;
        // Hard-break a token that cannot fit on its own line.
        while word.chars().count() > width {
            if !cur.is_empty() {
                lines.push(std::mem::take(&mut cur));
            }
            let cut = word.char_indices().nth(width).map(|(i, _)| i).unwrap_or(word.len());
            lines.push(word[..cut].to_string());
            word = &word[cut..];
        }
        let extra = if cur.is_empty() { 0 } else { 1 };
        if cur.chars().count() + extra + word.chars().count() > width {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        } else {
            if !cur.is_empty() {
                cur.push(' ');
            }
            cur.push_str(word);
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

// Horizontal window over a styled line, `width` cells wide, starting `offset` characters in. The
// focused row of a table keeps the height of every other row: a message longer than its column is
// read by panning with ←/→ rather than by wrapping the row taller than its neighbours. A `…` marks
// each side that still holds text and costs the one cell it takes.
fn line_window(line: &Line<'static>, offset: usize, width: usize) -> Line<'static> {
    if width == 0 {
        return Line::from("");
    }
    let chars: Vec<(char, Style)> = line
        .spans
        .iter()
        .flat_map(|s| {
            let style = s.style;
            s.content.chars().map(move |c| (c, style))
        })
        .collect();
    let start = offset.min(chars.len());
    let mut out: Vec<Span<'static>> = Vec::new();
    let mut avail = width;
    if start > 0 {
        out.push(Span::styled("…", Style::default().fg(DIM)));
        avail = avail.saturating_sub(1);
    }
    let more_right = chars.len() - start > avail;
    if more_right {
        avail = avail.saturating_sub(1);
    }
    let mut cur = String::new();
    let mut cur_style: Option<Style> = None;
    for (c, style) in chars.iter().skip(start).take(avail) {
        if cur_style != Some(*style) {
            if let Some(s) = cur_style {
                out.push(Span::styled(std::mem::take(&mut cur), s));
            }
            cur_style = Some(*style);
        }
        cur.push(*c);
    }
    if let Some(s) = cur_style {
        out.push(Span::styled(cur, s));
    }
    if more_right {
        out.push(Span::styled("…", Style::default().fg(DIM)));
    }
    Line::from(out)
}

// Furthest the pan may go: one cell of the window is spent on the left `…`, so the tail is only
// reachable if the bound accounts for it — stop short and the last character never shows.
fn msg_max_offset(len: usize, width: usize) -> usize {
    len.saturating_sub(width.saturating_sub(1))
}

// Width available for the flux MESSAGE column: inner width minus the fixed columns and the
// inter-column spacing (ratatui's default column_spacing is 1).
// Width taken off every table row by `highlight_symbol("> ")`.
const HIGHLIGHT_W: u16 = 2;

fn flux_msg_width(area_width: u16, fixed: u16, ncols: u16) -> usize {
    let inner = area_width.saturating_sub(2);
    let avail = inner.saturating_sub(fixed).saturating_sub(ncols.saturating_sub(1));
    // 20 is a readability floor, not an entitlement: `fixed` already holds back one cell of margin,
    // and on a narrow terminal a floor that claims more than is actually left spends exactly that
    // cell — putting the wrapped text back on the border the margin existed to keep it off. When
    // the two cannot both be had, the border wins and the column is simply narrower.
    avail.clamp(1, 20.max(avail)) as usize
}

// The `/` prompt. A single input line, no suggestion list: unlike the palette there is no closed
// set of valid answers to complete against. The hint line says what the query will do, which is not
// the same thing in a table view and in a scrolled text panel.
fn draw_search_popup(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let popup_w = 56.min(area.width.saturating_sub(2)).max(20);
    let popup_area = centered_rect(popup_w, 4, area);
    f.render_widget(Clear, popup_area);

    let st = lang::t(app.ai_language);
    let hint = if is_text_panel_mode(app.search_return_mode) {
        st.search_hint_text
    } else {
        st.search_hint_table
    };
    let lines = vec![
        Line::from(vec![
            Span::styled("/", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(
                app.search_input.clone(),
                Style::default().fg(Color::White).add_modifier(Modifier::BOLD),
            ),
            Span::styled("▏", Style::default().fg(Color::Yellow)),
        ]),
        Line::from(Span::styled(format!("  {}", hint), Style::default().fg(DIM))),
    ];

    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Yellow))
        .title(format!(" {} · Enter={} Esc ", st.mode_search, st.k_confirm));
    f.render_widget(Paragraph::new(lines).block(block), popup_area);
}

fn draw_command_popup(f: &mut ratatui::Frame, app: &App, area: Rect) {
    let suggestions = app.command_suggestions();

    let popup_w = 56.min(area.width.saturating_sub(2)).max(20);
    let popup_h = 4 + suggestions.len().min(6) as u16;
    let popup_area = centered_rect(popup_w, popup_h, area);
    f.render_widget(Clear, popup_area);

    let mut lines: Vec<Line<'static>> = Vec::new();
    lines.push(Line::from(vec![
        Span::styled(":", Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)),
        Span::styled(app.command_input.clone(), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
        Span::styled("▏", Style::default().fg(Color::Cyan)),
    ]));
    lines.push(Line::from(""));
    if suggestions.is_empty() {
        lines.push(Line::from(Span::styled(
            "  (aucune commande)",
            Style::default().fg(Color::Red),
        )));
    } else {
        // Scroll the 6-row window so the highlighted suggestion stays visible.
        const WINDOW: usize = 6;
        let cursor = app.command_cursor.min(suggestions.len().saturating_sub(1));
        let offset = cursor.saturating_sub(WINDOW - 1);
        for (i, name) in suggestions.iter().enumerate().skip(offset).take(WINDOW) {
            let style = if i == cursor {
                Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD)
            } else {
                Style::default().fg(Color::Gray)
            };
            lines.push(Line::from(Span::styled(format!("  {} ", name), style)));
        }
    }

    let st = lang::t(app.ai_language);
    let block = Block::default()
        .borders(Borders::ALL)
        .border_style(Style::default().fg(Color::Cyan))
        .title(format!(" {} · Tab={} Enter={} Esc ", st.mode_command, "autocomplete", st.k_confirm));
    f.render_widget(Paragraph::new(lines).block(block), popup_area);
}

fn loading_lines(
    stage: &str,
    started_at: Option<std::time::Instant>,
    sections_count: usize,
    model: &str,
    lang: AiLanguage,
) -> Vec<Line<'static>> {
    let spinner_chars = ['◐', '◓', '◑', '◒'];
    let now_ms = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_millis();
    let spinner = spinner_chars[(now_ms / 100) as usize % spinner_chars.len()];

    let elapsed_secs = started_at.map(|t| t.elapsed().as_secs_f32()).unwrap_or(0.0);
    let elapsed = format!("{:.1}s", elapsed_secs);

    let mut dots = String::new();
    for _ in 0..((now_ms / 400) as usize % 4) { dots.push('.'); }

    let st = lang::t(lang);
    let stage_text = if stage.is_empty() { st.lbl_preparation.to_string() } else { stage.to_string() };
    let (elapsed_label, resources_label, model_label, lang_label, hint) = (
        st.ai_elapsed,
        st.ai_resources,
        st.ai_model,
        st.ai_lang,
        st.ai_slow_hint,
    );

    vec![
        Line::from(""),
        Line::from(vec![
            Span::raw("  "),
            Span::styled(format!("{} ", spinner), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(stage_text, Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            Span::styled(dots, Style::default().fg(Color::Yellow)),
        ]),
        Line::from(""),
        Line::from(vec![
            Span::raw("    "),
            Span::styled(elapsed_label, Style::default().fg(DIM)),
            Span::styled(elapsed, Style::default().fg(Color::Cyan)),
        ]),
        Line::from(vec![
            Span::raw("    "),
            Span::styled(resources_label, Style::default().fg(DIM)),
            Span::styled(sections_count.to_string(), Style::default().fg(Color::Cyan)),
        ]),
        Line::from(vec![
            Span::raw("    "),
            Span::styled(model_label, Style::default().fg(DIM)),
            Span::styled(model.to_string(), Style::default().fg(Color::Cyan)),
            Span::styled(lang_label, Style::default().fg(DIM)),
            Span::styled(lang.label().to_string(), Style::default().fg(Color::Cyan)),
        ]),
        Line::from(""),
        Line::from(Span::styled(
            hint,
            Style::default().fg(DIM),
        )),
    ]
}

fn centered_rect(width: u16, height: u16, area: Rect) -> Rect {
    let x = area.x + area.width.saturating_sub(width) / 2;
    let y = area.y + area.height.saturating_sub(height) / 2;
    Rect::new(x, y, width.min(area.width), height.min(area.height))
}

// Flatten a styled line back to its plain text (used to copy what the detail panel shows).
fn line_plain(line: &Line) -> String {
    line.spans.iter().map(|s| s.content.as_ref()).collect()
}

// Indices of the lines containing the query. `q` is already lowercased.
fn text_match_lines(lines: &[Line], q: &str) -> Vec<usize> {
    lines
        .iter()
        .enumerate()
        .filter(|(_, l)| line_plain(l).to_lowercase().contains(q))
        .map(|(i, _)| i)
        .collect()
}

// Paint the matching lines, the current one brighter. The whole line is highlighted rather than the
// matched substring: the spans already carry their own colours, and splitting them to inject a
// boundary would mean rebuilding every styled segment of a log line. Only the background is set —
// the spans keep their foreground, so nothing becomes unreadable.
fn highlight_text_matches(lines: &mut [Line<'static>], hits: &[usize], current: usize) {
    for (rank, &i) in hits.iter().enumerate() {
        let Some(line) = lines.get_mut(i) else { continue };
        let bg = if rank == current { Color::Rgb(140, 110, 0) } else { Color::Rgb(60, 48, 0) };
        line.style = line.style.bg(bg);
    }
}

// Recompute the matches of a text panel, park the viewport on the current one when the user just
// asked to jump, and highlight them. Returns the scroll offset the panel should use, counted from
// the *top* — callers on the bottom-anchored convention convert it.
//
// It all happens in the draw pass because that is the only place that knows the panel's height,
// which is what decides where a match has to sit for the user to see it.
fn run_text_search(
    app: &mut App,
    lines: &mut Vec<Line<'static>>,
    visible: usize,
    current_top: usize,
) -> usize {
    let Some(q) = app.text_query.clone() else {
        app.text_search_hits.clear();
        return current_top;
    };
    let hits = text_match_lines(lines, &q);
    if hits.is_empty() {
        app.text_search_hits.clear();
        app.text_search_idx = 0;
        app.text_search_follow = false;
        return current_top;
    }
    // The panel's content changes under the search (logs stream, a diagnostic re-runs), so the
    // index is clamped every frame rather than assumed still valid.
    if app.text_search_idx >= hits.len() {
        app.text_search_idx = hits.len() - 1;
    }
    let top = if app.text_search_follow {
        app.text_search_follow = false;
        // Centre the match rather than putting it on the first line: in a log, the lines around a
        // match are most of the reason for looking for it.
        hits[app.text_search_idx].saturating_sub(visible / 2)
    } else {
        current_top
    };
    highlight_text_matches(lines, &hits, app.text_search_idx);
    app.text_search_hits = hits;
    top
}

// Plain text of the detail panel tab currently displayed, matching draw_detail's tab/node logic
// (RBAC has its own panel and is not handled here — copy is not wired for those modes).
fn detail_visible_text(app: &App) -> String {
    let is_node_mode = matches!(view_mode(app), Mode::Nodes | Mode::NodesFull | Mode::NodeUsage);
    let lines = if is_node_mode {
        status_lines(app)
    } else {
        match app.detail_tab {
            DetailTab::Logs => log_lines(app),
            DetailTab::Status => status_lines(app),
            DetailTab::Related => related_lines(app),
        }
    };
    lines.iter().map(line_plain).collect::<Vec<_>>().join("\n")
}

fn draw_detail(f: &mut ratatui::Frame, app: &mut App, area: ratatui::layout::Rect) {
    let is_rbac_mode = matches!(view_mode(app), Mode::Rbac | Mode::RbacFull);
    if is_rbac_mode {
        draw_rbac_detail(f, app, area);
        return;
    }
    let is_vuln_mode = matches!(view_mode(app), Mode::Vuln | Mode::VulnFull);
    if is_vuln_mode {
        draw_vuln_detail(f, app, area);
        return;
    }
    let is_secrets_mode = matches!(view_mode(app), Mode::Secrets | Mode::SecretsFull);
    if is_secrets_mode {
        draw_secrets_detail(f, app, area);
        return;
    }
    let is_certs_mode = matches!(view_mode(app), Mode::Certs | Mode::CertsFull);
    if is_certs_mode {
        draw_certs_detail(f, app, area);
        return;
    }

    let is_storage_mode = matches!(view_mode(app), Mode::Storage | Mode::StorageFull);
    if is_storage_mode {
        draw_storage_detail(f, app, area);
        return;
    }
    let is_capacity_mode = matches!(view_mode(app), Mode::Capacity | Mode::CapacityFull);
    if is_capacity_mode {
        draw_capacity_detail(f, app, area);
        return;
    }
    let is_kyverno_mode = matches!(view_mode(app), Mode::Kyverno | Mode::KyvernoFull);
    if is_kyverno_mode {
        draw_kyverno_detail(f, app, area);
        return;
    }
    let is_reflector_mode = matches!(view_mode(app), Mode::Reflector | Mode::ReflectorFull);
    if is_reflector_mode {
        draw_reflector_detail(f, app, area);
        return;
    }
    let is_velero_mode = matches!(view_mode(app), Mode::Velero | Mode::VeleroFull);
    if is_velero_mode {
        draw_velero_detail(f, app, area);
        return;
    }
    let is_k8c_mode = matches!(view_mode(app), Mode::K8ssandra | Mode::K8ssandraFull);
    if is_k8c_mode {
        draw_k8ssandra_detail(f, app, area);
        return;
    }
    let is_rancher_mode = matches!(view_mode(app), Mode::Rancher | Mode::RancherFull);
    if is_rancher_mode {
        draw_rancher_detail(f, app, area);
        return;
    }
    let is_argo_mode = matches!(view_mode(app), Mode::Argo | Mode::ArgoFull);
    if is_argo_mode {
        draw_argo_detail(f, app, area);
        return;
    }
    let is_identity_mode = matches!(view_mode(app), Mode::Identity | Mode::IdentityFull);
    if is_identity_mode {
        draw_identity_detail(f, app, area);
        return;
    }
    let is_configmaps_mode = matches!(view_mode(app), Mode::Configmaps | Mode::ConfigmapsFull);
    if is_configmaps_mode {
        draw_configmaps_detail(f, app, area);
        return;
    }
    let is_namespaces_mode = matches!(view_mode(app), Mode::Namespaces);
    if is_namespaces_mode {
        draw_namespaces_detail(f, app, area);
        return;
    }
    let is_node_mode = matches!(view_mode(app), Mode::Nodes | Mode::NodesFull | Mode::NodeUsage);
    let title = if is_node_mode {
        let name = {
            let s = app.node_list_state.lock().expect("node list poisoned");
            s.nodes.get(app.node_cursor).map(|n| n.name.clone()).unwrap_or_default()
        };
        Line::from(Span::styled(
            format!(" Node detail: {} ", name),
            Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD),
        ))
    } else {
        let mut spans = vec![
            tab_span("Logs", app.detail_tab == DetailTab::Logs),
            Span::raw(" │ "),
            tab_span("Status", app.detail_tab == DetailTab::Status),
            Span::raw(" │ "),
            tab_span("Related", app.detail_tab == DetailTab::Related),
        ];
        // What the Logs tab is actually showing has to be on screen: an empty panel means one thing
        // on the running container and the exact opposite on a previous run.
        if app.detail_tab == DetailTab::Logs {
            spans.extend(log_opts_spans(app));
        }
        Line::from(spans)
    };

    let mut lines: Vec<Line<'static>> = if is_node_mode {
        status_lines(app)
    } else {
        match app.detail_tab {
            DetailTab::Logs => log_lines(app),
            DetailTab::Status => status_lines(app),
            DetailTab::Related => related_lines(app),
        }
    };

    // Wrap the Status tab (and node status) so long condition messages — typically a Flux
    // reconciliation error — are fully visible instead of being cut at the right edge. Logs and
    // Related keep horizontal scrolling.
    let wrap_status = is_node_mode || app.detail_tab == DetailTab::Status;
    let visible = area.height.saturating_sub(2) as usize;
    // The scroll of a wrapped panel counts wrapped rows, not lines: the node panel is anchored on
    // its bottom, and counting raw lines would leave its last block (the taints) below the frame as
    // soon as a long annotation value wraps.
    let total: usize = if wrap_status {
        let wrap_w = area.width.saturating_sub(2) as usize;
        wrapped_panel_rows(&lines, wrap_w)
    } else {
        lines.len()
    };
    let max_scroll = total.saturating_sub(visible);

    // The Related tab is held at the top while pinned (re-evaluated each frame so it stays at the top
    // as the content streams in), until the user scrolls.
    let scroll_offset = if !is_node_mode && app.detail_tab == DetailTab::Related && app.related_pin_top {
        app.related_scroll = max_scroll;
        max_scroll
    } else {
        let target = app.scroll_target();
        if *target > max_scroll { *target = max_scroll; }
        *target
    };

    let mut scroll = if total > visible {
        (total - visible).saturating_sub(scroll_offset) as u16
    } else {
        0
    };

    // The search only runs when this panel is the whole screen: in the split view `/` filters the
    // table it follows, and under a popup (diagnostic, AI) the search belongs to the popup — running
    // it here would swallow the jump meant for what is on top.
    if matches!(
        view_mode(app),
        Mode::DetailFull | Mode::NodesFull | Mode::FluxFull | Mode::PodsFull | Mode::ServicesFull
    ) {
        let top = run_text_search(app, &mut lines, visible, scroll as usize);
        if top != scroll as usize {
            scroll = top.min(max_scroll) as u16;
            // The panel's own scroll counts up from the bottom; store the jump there too, or the
            // next arrow key would yank the viewport back to where it was.
            *app.scroll_target() = max_scroll.saturating_sub(scroll as usize);
        }
    }

    let block = Block::default().borders(Borders::ALL).title(title);
    let p = if wrap_status {
        Paragraph::new(lines)
            .wrap(Wrap { trim: false })
            .scroll((scroll, 0))
            .block(block)
    } else {
        Paragraph::new(lines)
            .scroll((scroll, app.detail_h_scroll as u16))
            .block(block)
    };
    f.render_widget(p, area);
}


// Badges appended to the detail tabs saying what the Logs tab is reading: the previous run, a
// single container, and whether the tail is refreshing on its own. Nothing is shown when all three
// are at their defaults, so the usual case reads exactly as before.
fn log_opts_spans(app: &App) -> Vec<Span<'static>> {
    let mut out = Vec::new();
    if app.log_opts.previous {
        out.push(Span::raw("  "));
        out.push(Span::styled(
            " previous ",
            Style::default().fg(Color::Black).bg(Color::Rgb(255, 140, 0)).add_modifier(Modifier::BOLD),
        ));
    }
    if let Some(c) = &app.log_opts.container {
        out.push(Span::raw(" "));
        out.push(Span::styled(
            format!(" {} ", c),
            Style::default().fg(Color::Black).bg(Color::Cyan),
        ));
    }
    if app.log_follow {
        out.push(Span::raw(" "));
        out.push(Span::styled(
            " ↻ follow ",
            Style::default().fg(Color::Black).bg(Color::Green),
        ));
    }
    out
}

fn tab_span(label: &str, active: bool) -> Span<'static> {
    if active {
        Span::styled(
            format!(" {} ", label),
            Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD),
        )
    } else {
        Span::styled(format!(" {} ", label), Style::default().fg(Color::Gray))
    }
}

// Dim vertical divider used to visually separate footer shortcut groups (nav · contextual · global).
fn footer_sep() -> Span<'static> {
    Span::styled("│  ", Style::default().fg(DIM))
}

// Blank columns between shortcuts so neighbouring key boxes never touch.
const FOOTER_COL_GAP: usize = 2;
// Width of footer_sep() once rendered ("│" plus its trailing gap).
const FOOTER_SEP_WIDTH: usize = 3;

// One shortcut: its key box plus the label spans that follow it.
type FooterCell = Vec<Span<'static>>;
// A run of related shortcuts, delimited by footer_sep() in the per-mode tables. A group is the
// unit of layout: it is never split across the two footer rows, so keys that belong together
// (a/w/e on the events view, r/z on Flux…) always stay side by side.
type FooterGroup = Vec<FooterCell>;

// Split a flat run of footer spans into groups of cells. A new cell starts at every key box (white
// background); labels attach to the current cell; every separator opens a new group.
fn footer_groups(spans: Vec<Span<'static>>) -> Vec<FooterGroup> {
    let mut groups: Vec<FooterGroup> = vec![Vec::new()];
    for span in spans {
        if span.content.starts_with('│') {
            groups.push(Vec::new());
            continue;
        }
        let is_key = span.style.bg == Some(Color::White);
        let group = groups.last_mut().expect("group present");
        if is_key || group.is_empty() {
            group.push(vec![span]);
        } else {
            group.last_mut().expect("cell present").push(span);
        }
    }
    groups.retain(|g| !g.is_empty());
    groups
}

// Visible width of a cell, ignoring the trailing padding baked into labels.
fn cell_width(cell: &[Span<'static>]) -> usize {
    let text: String = cell.iter().map(|s| s.content.as_ref()).collect();
    text.trim_end().chars().count()
}

// Rendered width of a group: every cell plus the gap that follows it.
fn group_width(group: &FooterGroup) -> usize {
    group.iter().map(|c| cell_width(c) + FOOTER_COL_GAP).sum()
}

// Total width of a row of groups, separators included.
fn row_width(groups: &[FooterGroup]) -> usize {
    let seps = groups.len().saturating_sub(1) * FOOTER_SEP_WIDTH;
    groups.iter().map(group_width).sum::<usize>() + seps
}

// Deal the groups over two rows of roughly equal length. The entry group (palette, back, quit)
// opens the top row and the tool bar closes the bottom one, so both anchors keep their usual spot;
// the groups in between go widest-first to whichever row is currently shorter, then are put back in
// authoring order inside their row. Everything stays on a single row when it fits.
fn balance_footer_rows(
    groups: Vec<FooterGroup>,
    tools: FooterGroup,
    avail: usize,
) -> (Vec<FooterGroup>, Vec<FooterGroup>) {
    let mut all = groups;
    all.push(tools);
    if row_width(&all) <= avail {
        return (all, Vec::new());
    }
    let tools = all.pop().expect("tool bar present");
    if all.is_empty() {
        return (Vec::new(), vec![tools]);
    }

    let mut order: Vec<usize> = (1..all.len()).collect();
    order.sort_by_key(|&i| std::cmp::Reverse(group_width(&all[i])));
    let mut top_idx: Vec<usize> = vec![0];
    let mut bottom_idx: Vec<usize> = Vec::new();
    let mut top_w = group_width(&all[0]);
    let mut bottom_w = group_width(&tools);
    for i in order {
        let w = group_width(&all[i]) + FOOTER_SEP_WIDTH;
        if top_w <= bottom_w {
            top_idx.push(i);
            top_w += w;
        } else {
            bottom_idx.push(i);
            bottom_w += w;
        }
    }
    top_idx.sort_unstable();
    bottom_idx.sort_unstable();

    let mut slots: Vec<Option<FooterGroup>> = all.into_iter().map(Some).collect();
    let mut take = |idx: &[usize]| -> Vec<FooterGroup> {
        idx.iter()
            .map(|&i| slots[i].take().expect("group taken once"))
            .collect()
    };
    let top = take(&top_idx);
    let mut bottom = take(&bottom_idx);
    bottom.push(tools);
    (top, bottom)
}

// Emit a row: cells separated by a fixed gap, groups by a dim divider. Trailing whitespace baked
// into labels is stripped first so the gap lands exactly where expected.
fn render_footer_row(groups: &[FooterGroup]) -> Vec<Span<'static>> {
    let mut out: Vec<Span<'static>> = Vec::new();
    for (gi, group) in groups.iter().enumerate() {
        if gi > 0 {
            out.push(footer_sep());
        }
        for cell in group {
            let last = cell.iter().rposition(|s| !s.content.trim_end().is_empty());
            if let Some(last) = last {
                for span in cell.iter().take(last) {
                    out.push(span.clone());
                }
                let span = &cell[last];
                out.push(Span::styled(span.content.trim_end().to_string(), span.style));
            }
            out.push(Span::raw(" ".repeat(FOOTER_COL_GAP)));
        }
    }
    out
}

fn filter_label(label: &str, active: bool) -> Span<'static> {
    let style = if active {
        Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD)
    } else {
        Style::default().fg(DIM)
    };
    Span::styled(label.to_string(), style)
}

fn log_lines(app: &App) -> Vec<Line<'static>> {
    let s = app.log_state.lock().expect("log state poisoned");
    if let Some(e) = &s.error {
        return vec![Line::from(Span::styled(e.clone(), Style::default().fg(Color::Red)))];
    }
    if s.loading && s.lines.is_empty() {
        return vec![Line::from("(loading...)")];
    }
    s.lines.iter().map(|l| colorize_log_line(l)).collect()
}

// Status glyph + colour for an applied inventory object (shared by the tree rows).
fn inventory_glyph(it: &InventoryItem) -> (&'static str, Color) {
    if it.reconciling {
        ("↻", Color::Cyan)
    } else {
        match it.ready {
            Some(true) => ("✓", Color::Green),
            Some(false) => ("✗", Color::Red),
            None => ("·", DIM),
        }
    }
}

fn flux_logs_lines(app: &App) -> Vec<Line<'static>> {
    let s = app.flux_logs_state.lock().expect("log state poisoned");
    if let Some(e) = &s.error {
        return vec![Line::from(Span::styled(e.clone(), Style::default().fg(Color::Red)))];
    }
    if s.loading && s.lines.is_empty() {
        return vec![Line::from("(loading...)")];
    }
    s.lines.iter().map(|l| colorize_log_line(l)).collect()
}

// Full-screen aggregated view of every Flux controller log (the `flux logs` view).
fn draw_flux_logs(f: &mut ratatui::Frame, app: &mut App) -> usize {
    let area = f.area();
    let layout = Layout::default()
        .direction(Direction::Vertical)
        .constraints([Constraint::Length(2), Constraint::Min(3), Constraint::Length(1)])
        .split(area);

    let header = Paragraph::new(vec![
        Line::from(vec![
            Span::styled(
                format!(" kdt v{} ", env!("CARGO_PKG_VERSION")),
                Style::default().fg(Color::Black).bg(Color::Cyan).add_modifier(Modifier::BOLD),
            ),
            Span::raw(format!("  ctx={}  flux logs (tous controllers, suivi 3 s)", app.context_label)),
        ]),
        cluster_banner_line(app),
    ]);
    f.render_widget(header, layout[0]);

    let mut lines = flux_logs_lines(app);
    let visible = layout[1].height.saturating_sub(2) as usize;
    let total = lines.len();
    let max_scroll = total.saturating_sub(visible);
    let scroll_offset = {
        let target = app.scroll_target();
        if *target > max_scroll { *target = max_scroll; }
        *target
    };
    let mut scroll = if total > visible {
        (total - visible).saturating_sub(scroll_offset) as u16
    } else {
        0
    };
    let top = run_text_search(app, &mut lines, visible, scroll as usize);
    if top != scroll as usize {
        scroll = top.min(max_scroll) as u16;
        *app.scroll_target() = max_scroll.saturating_sub(scroll as usize);
    }
    let p = Paragraph::new(lines)
        .scroll((scroll, 0))
        .block(Block::default().borders(Borders::ALL).title("flux logs"));
    f.render_widget(p, layout[1]);

    let footer = Paragraph::new(Line::from(Span::styled(
        lang::t(app.ai_language).logs_footer,
        Style::default().fg(DIM),
    )));
    f.render_widget(footer, layout[2]);

    visible
}

fn colorize_log_line(l: &str) -> Line<'static> {
    if l.starts_with("══ ") {
        return Line::from(Span::styled(
            l.to_string(),
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        ));
    }
    let st = lang::active();
    // The log-fetch failure carries the container name, so only its fixed head can be matched.
    let fetch_failed_head = st
        .ev_log_fetch_failed
        .split('{')
        .next()
        .unwrap_or(st.ev_log_fetch_failed);
    if l.starts_with(st.ev_no_log) || l.starts_with(fetch_failed_head) {
        return Line::from(Span::styled(l.to_string(), Style::default().fg(DIM)));
    }
    let bytes = l.as_bytes();
    if bytes.len() > 5
        && matches!(bytes[0], b'I' | b'W' | b'E' | b'F')
        && bytes[1..5].iter().all(|c| c.is_ascii_digit())
    {
        let style = match bytes[0] {
            b'E' | b'F' => Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
            b'W' => Style::default().fg(Color::Yellow),
            _ => Style::default().fg(Color::Gray),
        };
        return Line::from(Span::styled(l.to_string(), style));
    }
    let lower = l.to_lowercase();
    let style = if lower.contains("error")
        || lower.contains("err]") || lower.contains("[err ")
        || lower.contains("fatal") || lower.contains("panic")
        || lower.contains("\"error\"") || lower.contains("level=error")
        || lower.contains(" failed") || lower.starts_with("failed")
    {
        Style::default().fg(Color::Red)
    } else if lower.contains("warn") || lower.contains("\"warning\"") || lower.contains("level=warn") {
        Style::default().fg(Color::Yellow)
    } else if lower.contains("debug") || lower.contains("trace") || lower.contains("level=debug") {
        Style::default().fg(DIM)
    } else if lower.contains("info") || lower.contains("level=info") {
        Style::default().fg(Color::Gray)
    } else if l.starts_with("    at ") || l.starts_with("\tat ") || l.starts_with("Caused by") {
        Style::default().fg(DIM)
    } else {
        Style::default()
    };
    Line::from(Span::styled(l.to_string(), style))
}

fn status_lines(app: &App) -> Vec<Line<'static>> {
    let s = app.status_state.lock().expect("status state poisoned");
    if let Some(e) = &s.error {
        return vec![Line::from(Span::styled(e.clone(), Style::default().fg(Color::Red)))];
    }
    if s.loading && s.lines.is_empty() {
        return vec![Line::from("(loading...)")];
    }
    s.lines
        .iter()
        .map(|(c, t)| Line::from(Span::styled(t.clone(), Style::default().fg(line_color(*c)))))
        .collect()
}

fn related_lines(app: &App) -> Vec<Line<'static>> {
    let st = lang::t(app.ai_language);
    let Some(idx) = app.table_state.selected() else { return Vec::new(); };
    let Some(rec) = app.snapshot.get(idx) else { return Vec::new(); };
    let target_ns = rec.namespace.clone();
    let target_name = rec.name.clone();
    let target_kind = rec.kind.clone();

    let mut lines: Vec<Line<'static>> = Vec::new();

    let event_lines: Vec<Line<'static>> = {
        let buf = app.buffer.lock().expect("buffer poisoned");
        buf.iter()
            .filter(|r| r.namespace == target_ns && r.name == target_name && r.kind == target_kind)
            .map(|r| {
                let msg_style = match r.severity {
                    Severity::Warning if is_critical_reason(&r.reason) => Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
                    Severity::Warning => Style::default().fg(Color::Yellow),
                    Severity::Normal => Style::default().fg(Color::Gray),
                };
                let component = if r.component.is_empty() { String::new() } else { format!(" [{}]", r.component) };
                Line::from(vec![
                    Span::styled(format_time(r), Style::default().fg(DIM)),
                    Span::raw("  "),
                    Span::styled(r.reason.clone(), Style::default().fg(Color::Cyan)),
                    Span::styled(component, Style::default().fg(DIM)),
                    Span::raw("  "),
                    Span::styled(r.message.clone(), msg_style),
                    Span::styled(format!("  x{}", r.count), Style::default().fg(DIM)),
                ])
            })
            .collect()
    };

    if !event_lines.is_empty() {
        lines.push(Line::from(Span::styled(
            st.rel_events_header,
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        )));
        lines.extend(event_lines);
    }

    let (loading, sections, error) = {
        let s = app.related_state.lock().expect("related state poisoned");
        (s.loading, s.sections.clone(), s.error.clone())
    };

    if loading || !sections.is_empty() || error.is_some() {
        if !lines.is_empty() { lines.push(Line::from("")); }
        lines.push(Line::from(Span::styled(
            st.rel_context_header,
            Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD),
        )));
        if let Some(e) = error {
            lines.push(Line::from(Span::styled(e, Style::default().fg(Color::Red))));
        } else if loading && sections.is_empty() {
            lines.push(Line::from(Span::styled(st.rel_fetching, Style::default().fg(Color::Yellow))));
        } else if sections.is_empty() {
            lines.push(Line::from(Span::styled(st.rel_none, Style::default().fg(DIM))));
        } else {
            for (title, body) in sections.iter() {
                lines.push(Line::from(""));
                lines.push(Line::from(Span::styled(
                    format!("> {}", title),
                    Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
                )));
                let display = pretty_json_for_display(body);
                for body_line in display.lines() {
                    lines.push(colorize_json_line(body_line));
                }
            }
        }
    }

    lines
}

// Re-expand a compact JSON section body to indented multi-line form for display. The stored body is
// compact (token-minimal for the AI); a trailing truncation marker or a cut object falls back to raw.
fn pretty_json_for_display(body: &str) -> String {
    let (json, suffix) = match body.split_once("\n... ") {
        Some((j, s)) => (j, Some(s)),
        None => (body, None),
    };
    match serde_json::from_str::<serde_json::Value>(json) {
        Ok(v) => match serde_json::to_string_pretty(&v) {
            Ok(mut p) => {
                if let Some(s) = suffix {
                    p.push_str("\n... ");
                    p.push_str(s);
                }
                p
            }
            Err(_) => body.to_string(),
        },
        Err(_) => body.to_string(),
    }
}

fn colorize_json_line(line: &str) -> Line<'static> {
    let trimmed = line.trim_start();
    let indent_len = line.len() - trimmed.len();
    let indent = line[..indent_len].to_string();

    if trimmed.is_empty() {
        return Line::from(line.to_string());
    }

    if matches!(trimmed, "{" | "}" | "[" | "]" | "}," | "],") || trimmed == "}, {" {
        return Line::from(Span::styled(line.to_string(), Style::default().fg(DIM)));
    }

    if let Some(after_quote) = trimmed.strip_prefix('"') {
        if let Some(end_q) = after_quote.find('"') {
            let key_full = &trimmed[..end_q + 2];
            let after_key = &trimmed[end_q + 2..];
            if let Some(after_colon) = after_key.strip_prefix(':') {
                let value_part = after_colon.trim_start();
                let value_style = if value_part.starts_with('"') {
                    Style::default().fg(Color::Green)
                } else if value_part.starts_with(|c: char| c.is_ascii_digit() || c == '-')
                    || value_part.starts_with("true")
                    || value_part.starts_with("false")
                {
                    Style::default().fg(Color::Magenta)
                } else if value_part.starts_with("null") {
                    Style::default().fg(DIM)
                } else {
                    Style::default().fg(Color::Gray)
                };
                let sep_offset = end_q + 2;
                let value_offset = sep_offset + 1;
                let separator = ":".to_string();
                let value_with_pad = trimmed[value_offset..].to_string();
                return Line::from(vec![
                    Span::raw(indent),
                    Span::styled(key_full.to_string(), Style::default().fg(Color::Cyan)),
                    Span::styled(separator, Style::default().fg(DIM)),
                    Span::styled(value_with_pad, value_style),
                ]);
            }
        }
    }

    Line::from(Span::styled(line.to_string(), Style::default().fg(Color::Gray)))
}

fn render_markdown_lines(content: &str, width: usize) -> Vec<Line<'static>> {
    let mut out = Vec::new();
    let mut in_code_block = false;
    let mut table_buf: Vec<String> = Vec::new();
    for line in content.lines() {
        let trimmed = line.trim_start();

        if !in_code_block && trimmed.starts_with('|') && trimmed[1..].contains('|') {
            table_buf.push(trimmed.to_string());
            continue;
        }
        if !table_buf.is_empty() {
            render_table_block(&table_buf, width, &mut out);
            table_buf.clear();
        }

        if trimmed.starts_with("```") {
            in_code_block = !in_code_block;
            out.push(Line::from(Span::styled(line.to_string(), Style::default().fg(DIM))));
            continue;
        }
        if in_code_block {
            out.push(Line::from(Span::styled(line.to_string(), Style::default().fg(Color::Green))));
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("### ") {
            out.push(Line::from(Span::styled(format!("### {}", rest), Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))));
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("## ") {
            out.push(Line::from(Span::styled(format!("## {}", rest), Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD))));
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("# ") {
            out.push(Line::from(Span::styled(format!("# {}", rest), Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD | Modifier::UNDERLINED))));
            continue;
        }
        if trimmed.starts_with("- ") || trimmed.starts_with("* ") {
            let indent = &line[..line.len() - trimmed.len()];
            let rest = &trimmed[2..];
            let mut spans = vec![
                Span::raw(indent.to_string()),
                Span::styled("• ", Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD)),
            ];
            spans.extend(render_inline_spans(rest));
            out.push(Line::from(spans));
            continue;
        }
        let bytes = trimmed.as_bytes();
        if bytes.len() >= 3 && bytes[0].is_ascii_digit() && (bytes[1] == b'.' || (bytes[1].is_ascii_digit() && bytes[2] == b'.')) {
            let indent = &line[..line.len() - trimmed.len()];
            let mut spans = vec![Span::raw(indent.to_string())];
            spans.extend(render_inline_spans_with_first_bold(trimmed));
            out.push(Line::from(spans));
            continue;
        }
        if let Some(rest) = trimmed.strip_prefix("> ") {
            out.push(Line::from(Span::styled(format!("> {}", rest), Style::default().fg(Color::Magenta))));
            continue;
        }

        let indent = &line[..line.len() - trimmed.len()];
        let mut spans = vec![Span::raw(indent.to_string())];
        spans.extend(render_inline_spans(trimmed));
        out.push(Line::from(spans));
    }
    if !table_buf.is_empty() {
        render_table_block(&table_buf, width, &mut out);
    }
    out
}

fn split_table_row(line: &str) -> Vec<String> {
    let s = line.trim();
    let s = s.strip_prefix('|').unwrap_or(s);
    let s = s.strip_suffix('|').unwrap_or(s);
    s.split('|')
        .map(|c| c.split_whitespace().collect::<Vec<_>>().join(" "))
        .collect()
}

fn is_table_separator(cells: &[String]) -> bool {
    !cells.is_empty()
        && cells.iter().all(|c| {
            let t = c.trim();
            !t.is_empty() && t.chars().all(|ch| ch == '-' || ch == ':' || ch == ' ')
        })
}

fn wrap_cell(text: &str, w: usize) -> Vec<String> {
    if w == 0 {
        return vec![String::new()];
    }
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in text.split(' ') {
        if word.chars().count() > w {
            if !cur.is_empty() {
                lines.push(std::mem::take(&mut cur));
            }
            let mut chunk = String::new();
            for ch in word.chars() {
                if chunk.chars().count() == w {
                    lines.push(std::mem::take(&mut chunk));
                }
                chunk.push(ch);
            }
            cur = chunk;
            continue;
        }
        let add = if cur.is_empty() { word.chars().count() } else { cur.chars().count() + 1 + word.chars().count() };
        if add > w {
            lines.push(std::mem::take(&mut cur));
            cur.push_str(word);
        } else {
            if !cur.is_empty() {
                cur.push(' ');
            }
            cur.push_str(word);
        }
    }
    if !cur.is_empty() || lines.is_empty() {
        lines.push(cur);
    }
    lines
}

fn render_table_block(buf: &[String], width: usize, out: &mut Vec<Line<'static>>) {
    let rows: Vec<Vec<String>> = buf.iter().map(|l| split_table_row(l)).collect();
    let ncols = rows.iter().map(|r| r.len()).max().unwrap_or(0);
    if ncols == 0 {
        return;
    }
    let body: Vec<&Vec<String>> = rows.iter().filter(|r| !is_table_separator(r)).collect();
    if body.is_empty() {
        return;
    }

    let mut natural = vec![0usize; ncols];
    for r in &body {
        for (i, c) in r.iter().enumerate() {
            natural[i] = natural[i].max(c.chars().count());
        }
    }

    let sep = " │ ";
    let overhead = sep.chars().count() * ncols.saturating_sub(1);
    let budget = width.saturating_sub(overhead).max(ncols * 4);
    let total: usize = natural.iter().sum();
    let col_w: Vec<usize> = if total <= budget {
        natural.clone()
    } else {
        let mut w: Vec<usize> = natural
            .iter()
            .map(|&n| ((n * budget) / total.max(1)).max(6))
            .collect();
        let mut over = w.iter().sum::<usize>().saturating_sub(budget);
        while over > 0 {
            if let Some((idx, _)) = w.iter().enumerate().max_by_key(|(_, &v)| v) {
                if w[idx] <= 6 {
                    break;
                }
                w[idx] -= 1;
                over -= 1;
            } else {
                break;
            }
        }
        w
    };

    let header_style = Style::default().fg(Color::Cyan).add_modifier(Modifier::BOLD);
    for (ri, row) in body.iter().enumerate() {
        let is_header = ri == 0;
        let wrapped: Vec<Vec<String>> = (0..ncols)
            .map(|i| {
                let cell = row.get(i).map(|s| s.as_str()).unwrap_or("");
                wrap_cell(cell, col_w[i])
            })
            .collect();
        let height = wrapped.iter().map(|c| c.len()).max().unwrap_or(1);
        for h in 0..height {
            let mut spans: Vec<Span<'static>> = Vec::new();
            for i in 0..ncols {
                if i > 0 {
                    spans.push(Span::styled(sep.to_string(), Style::default().fg(DIM)));
                }
                let txt = wrapped[i].get(h).cloned().unwrap_or_default();
                let pad = col_w[i].saturating_sub(txt.chars().count());
                let padded = format!("{}{}", txt, " ".repeat(pad));
                if is_header {
                    spans.push(Span::styled(padded, header_style));
                } else {
                    spans.push(Span::raw(padded));
                }
            }
            out.push(Line::from(spans));
        }
        if is_header {
            let total_w: usize = col_w.iter().sum::<usize>() + overhead;
            out.push(Line::from(Span::styled(
                "─".repeat(total_w.min(width.max(1))),
                Style::default().fg(DIM),
            )));
        }
    }
    out.push(Line::from(""));
}

fn render_inline_spans_with_first_bold(s: &str) -> Vec<Span<'static>> {
    if let Some(idx) = s.find(' ') {
        let (head, tail) = s.split_at(idx);
        let mut spans = vec![Span::styled(head.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))];
        spans.extend(render_inline_spans(tail));
        spans
    } else {
        vec![Span::styled(s.to_string(), Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD))]
    }
}

fn render_inline_spans(line: &str) -> Vec<Span<'static>> {
    let mut spans: Vec<Span<'static>> = Vec::new();
    let mut buf = String::new();
    let mut in_code = false;
    let mut bold = false;
    let mut chars = line.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '`' {
            flush(&mut spans, &mut buf, in_code, bold);
            in_code = !in_code;
            continue;
        }
        if !in_code && c == '*' && chars.peek() == Some(&'*') {
            chars.next();
            flush(&mut spans, &mut buf, in_code, bold);
            bold = !bold;
            continue;
        }
        buf.push(c);
    }
    flush(&mut spans, &mut buf, in_code, bold);
    if spans.is_empty() {
        spans.push(Span::raw(String::new()));
    }
    spans
}

fn flush(spans: &mut Vec<Span<'static>>, buf: &mut String, in_code: bool, bold: bool) {
    if buf.is_empty() { return; }
    let mut style = Style::default();
    if in_code {
        style = style.fg(Color::Green);
    }
    if bold {
        style = style.add_modifier(Modifier::BOLD);
    }
    spans.push(Span::styled(std::mem::take(buf), style));
}

fn line_color(c: LineColor) -> Color {
    match c {
        LineColor::Plain => Color::White,
        LineColor::Ok => Color::Green,
        LineColor::Warn => Color::Yellow,
        LineColor::Err => Color::Red,
        LineColor::Info => Color::Cyan,
        LineColor::Dim => DIM,
    }
}

fn row_for(r: &EventRecord, h_scroll: usize) -> Row<'static> {
    let time_str = format_time(r);
    let (sev_label, sev_style) = match r.severity {
        Severity::Warning if is_critical_reason(&r.reason) => (
            "ERR",
            Style::default().fg(Color::Red).add_modifier(Modifier::BOLD),
        ),
        Severity::Warning => (
            "WARN",
            Style::default().fg(Color::Yellow).add_modifier(Modifier::BOLD),
        ),
        Severity::Normal => ("OK", Style::default().fg(Color::Green)),
    };
    let reason_style = if r.severity == Severity::Warning && is_critical_reason(&r.reason) {
        Style::default().fg(Color::Red).add_modifier(Modifier::BOLD)
    } else if r.severity == Severity::Warning {
        Style::default().fg(Color::Yellow)
    } else {
        Style::default().fg(Color::Cyan)
    };
    let row_style = match r.severity {
        Severity::Warning if is_critical_reason(&r.reason) => Style::default().fg(Color::White).bg(Color::Rgb(40, 0, 0)),
        Severity::Warning => Style::default().fg(Color::White),
        Severity::Normal => Style::default().fg(Color::Gray),
    };

    let message = slice_from(&r.message, h_scroll);

    Row::new(vec![
        Cell::from(time_str).style(Style::default().fg(DIM)),
        Cell::from(sev_label).style(sev_style),
        Cell::from(r.namespace.clone()),
        Cell::from(r.kind.clone()),
        Cell::from(r.name.clone()),
        Cell::from(r.reason.clone()).style(reason_style),
        Cell::from(format!("x{}", r.count)),
        Cell::from(message),
    ])
    .style(row_style)
}

// Horizontal scroll helper: return `s` with the first `n` characters dropped.
fn slice_from(s: &str, n: usize) -> String {
    if n == 0 { s.to_string() } else { s.chars().skip(n).collect() }
}

// Format a node's usage as a (title, body) prompt section: totals plus per-container detail,
// limited to containers with an issue and capped at 80 rows.
fn format_node_usage_for_ai(s: &crate::events::NodeUsageState) -> (String, String) {
    let st = lang::active();
    use crate::events::{format_cpu_milli, format_memory_bytes};
    let mut body = String::new();
    body.push_str(&format!("Node allocatable: cpu={}, memory={}\n",
        format_cpu_milli(s.alloc_cpu_milli), format_memory_bytes(s.alloc_mem_bytes)));
    body.push_str(&format!("metrics-server: {}\n",
        if s.metrics_available { "available" } else { "unavailable (use=null)" }));

    let (mut user_cpu_req, mut user_mem_req) = (0_i64, 0_i64);
    let (mut user_cpu_lim, mut user_mem_lim) = (0_i64, 0_i64);
    let (mut user_cpu_use, mut user_mem_use) = (0_i64, 0_i64);
    let (mut sys_cpu_req, mut sys_mem_req) = (0_i64, 0_i64);
    let (mut sys_cpu_use, mut sys_mem_use) = (0_i64, 0_i64);
    let mut user_n = 0; let mut sys_n = 0;
    for r in &s.rows {
        let (cr, lr, ur, mr, ml, mu) = (
            r.cpu_req.unwrap_or(0), r.cpu_lim.unwrap_or(0), r.cpu_use.unwrap_or(0),
            r.mem_req.unwrap_or(0), r.mem_lim.unwrap_or(0), r.mem_use.unwrap_or(0),
        );
        if r.is_system {
            sys_n += 1;
            sys_cpu_req += cr; sys_mem_req += mr; sys_cpu_use += ur; sys_mem_use += mu;
        } else {
            user_n += 1;
            user_cpu_req += cr; user_cpu_lim += lr; user_cpu_use += ur;
            user_mem_req += mr; user_mem_lim += ml; user_mem_use += mu;
        }
    }
    body.push_str(&format!(
        "\nUser containers ({}): cpu req={} lim={} use={}, mem req={} lim={} use={}\n",
        user_n,
        format_cpu_milli(user_cpu_req), format_cpu_milli(user_cpu_lim), format_cpu_milli(user_cpu_use),
        format_memory_bytes(user_mem_req), format_memory_bytes(user_mem_lim), format_memory_bytes(user_mem_use),
    ));
    body.push_str(&lang::fill(
        st.prompt_sys_containers,
        &[
            ("n", &sys_n.to_string()),
            ("creq", &format_cpu_milli(sys_cpu_req)),
            ("cuse", &format_cpu_milli(sys_cpu_use)),
            ("mreq", &format_memory_bytes(sys_mem_req)),
            ("muse", &format_memory_bytes(sys_mem_use)),
        ],
    ));

    body.push_str(st.prompt_per_container_details_full);
    let mut printed = 0;
    for r in &s.rows {
        let cpu_at_limit = matches!((r.cpu_use, r.cpu_lim), (Some(u), Some(l)) if l > 0 && u >= l);
        let mem_at_limit = matches!((r.mem_use, r.mem_lim), (Some(u), Some(l)) if l > 0 && u >= l);
        let cpu_under = matches!((r.cpu_req, r.cpu_use), (Some(req), Some(u)) if req > 0 && u * 100 / req < 30);
        let mem_under = matches!((r.mem_req, r.mem_use), (Some(req), Some(u)) if req > 0 && u * 100 / req < 30);
        let cpu_over_lim = matches!((r.cpu_lim, r.cpu_req), (Some(l), Some(rq)) if rq > 0 && l > rq * 4);
        let mem_over_lim = matches!((r.mem_lim, r.mem_req), (Some(l), Some(rq)) if rq > 0 && l > rq * 4);
        let has_issue = cpu_at_limit || mem_at_limit || cpu_under || mem_under || cpu_over_lim || mem_over_lim
            || r.cpu_req.is_none() || r.mem_req.is_none() || r.mem_lim.is_none();
        if !has_issue { continue; }
        if printed >= 80 { body.push_str(st.prompt_list_truncated); break; }
        printed += 1;
        let mut tags = Vec::new();
        if r.cpu_req.is_none() { tags.push("noCpuReq"); }
        if r.mem_req.is_none() { tags.push("noMemReq"); }
        if r.mem_lim.is_none() { tags.push("noMemLim"); }
        if cpu_under { tags.push("cpuOver"); }
        if mem_under { tags.push("memOver"); }
        if cpu_over_lim { tags.push("cpuLim>>"); }
        if mem_over_lim { tags.push("memLim>>"); }
        if cpu_at_limit { tags.push("cpuMax"); }
        if mem_at_limit { tags.push("OOMrisk"); }
        let opt = |v: Option<i64>, fmt: fn(i64) -> String| v.map(fmt).unwrap_or_else(|| "-".to_string());
        body.push_str(&format!(
            "{}{}/{} [{}] cpu={}/{}/{} mem={}/{}/{} ready={} rst={} -> {}\n",
            if r.is_system { "[sys] " } else { "" },
            r.namespace, r.pod, r.container,
            opt(r.cpu_req, format_cpu_milli), opt(r.cpu_lim, format_cpu_milli), opt(r.cpu_use, format_cpu_milli),
            opt(r.mem_req, format_memory_bytes), opt(r.mem_lim, format_memory_bytes), opt(r.mem_use, format_memory_bytes),
            if r.ready { "Y" } else { "N" }, r.restarts,
            tags.join(","),
        ));
    }
    body.push_str(st.prompt_sys_note);
    ("Node usage (per-container avec issues)".to_string(), body)
}

fn format_time(r: &EventRecord) -> String {
    let s = r.time.to_string();
    if let Some(t) = s.split('T').nth(1) {
        t.split('.').next().unwrap_or(t).trim_end_matches('Z').to_string()
    } else {
        s
    }
}

// Snapshot the last 200 log lines for inclusion in the AI prompt (or a placeholder if unavailable).
// Char budgets for the high-volume free-text prompt sections. Logs and status are kept by their
// tail (most recent/most diagnostic content) once over budget.
const MAX_LOGS_CHARS: usize = 12_000;
const MAX_STATUS_CHARS: usize = 6_000;
const MAX_RELATED_LINES: usize = 50;

// Collapse runs of identical consecutive lines into "<line>  (xN)" so repeated log/status spam does
// not eat the token budget verbatim.
fn collapse_repeats<'a>(lines: impl IntoIterator<Item = &'a str>) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    let mut run: Option<(&'a str, usize)> = None;
    let flush = |out: &mut Vec<String>, line: &str, n: usize| {
        out.push(if n > 1 { format!("{line}  (x{n})") } else { line.to_string() });
    };
    for line in lines {
        match run {
            Some((prev, n)) if prev == line => run = Some((prev, n + 1)),
            Some((prev, n)) => { flush(&mut out, prev, n); run = Some((line, 1)); }
            None => run = Some((line, 1)),
        }
    }
    if let Some((prev, n)) = run { flush(&mut out, prev, n); }
    out
}

// Keep the last `max` chars of `s` (recent content is the most diagnostic for logs/status),
// aligned to a char boundary and prefixed with an elision marker when truncated.
fn cap_chars_tail(s: String, max: usize) -> String {
    if s.len() <= max { return s; }
    let mut start = s.len() - max;
    while start < s.len() && !s.is_char_boundary(start) { start += 1; }
    lang::fill(lang::active().prompt_truncated, &[("body", &s[start..])])
}

// `None` means "there is nothing here", and the section is then left out of the prompt entirely:
// an empty heading costs tokens and, worse, reads as a hole the model may try to fill. An error or a
// pending fetch is not nothing — that text stays, because "logs unavailable: forbidden" is a fact
// about the cluster the analysis needs.
fn capture_logs_text(state: &SharedLog) -> Option<String> {
    let st = lang::active();
    let s = state.lock().expect("log state poisoned");
    if let Some(e) = &s.error { return Some(lang::fill(st.cap_unavailable, &[("e", e)])); }
    if s.loading && s.lines.is_empty() { return Some(st.cap_loading.to_string()); }
    if s.lines.is_empty() { return None; }
    let n = s.lines.len();
    let start = n.saturating_sub(200);
    let collapsed = collapse_repeats(s.lines[start..].iter().map(|l| l.as_str()));
    Some(cap_chars_tail(collapsed.join("\n"), MAX_LOGS_CHARS))
}

fn capture_status_text(state: &SharedStatus) -> Option<String> {
    let st = lang::active();
    let s = state.lock().expect("status state poisoned");
    if let Some(e) = &s.error { return Some(lang::fill(st.cap_unavailable, &[("e", e)])); }
    if s.loading && s.lines.is_empty() { return Some(st.cap_loading.to_string()); }
    if s.lines.is_empty() { return None; }
    let collapsed = collapse_repeats(s.lines.iter().map(|(_, t)| t.as_str()));
    Some(cap_chars_tail(collapsed.join("\n"), MAX_STATUS_CHARS))
}

// Aggregate buffered events for the same object into the prompt's "related events" section.
// Duplicates (same severity/reason/message) collapse into one line, summing their occurrence
// counts and keeping the most recent timestamp, then the 50 most recent lines are kept.
fn capture_related_text(buffer: &SharedBuffer, rec: &EventRecord) -> Option<String> {
    let buf = buffer.lock().expect("buffer poisoned");
    use k8s_openapi::jiff::Timestamp;
    let mut order: Vec<(Severity, String, String)> = Vec::new();
    let mut agg: std::collections::HashMap<(Severity, String, String), (Timestamp, i64)> =
        std::collections::HashMap::new();
    for r in buf.iter().filter(|r| r.namespace == rec.namespace && r.name == rec.name && r.kind == rec.kind) {
        let key = (r.severity, r.reason.clone(), r.message.clone());
        match agg.get_mut(&key) {
            Some((time, count)) => {
                *count += r.count.max(1) as i64;
                if r.time > *time { *time = r.time; }
            }
            None => {
                order.push(key.clone());
                agg.insert(key, (r.time, r.count.max(1) as i64));
            }
        }
    }
    let mut related: Vec<(Timestamp, String)> = order
        .into_iter()
        .map(|key| {
            let (time, count) = agg[&key];
            let (sev, reason, message) = key;
            let line = format!(
                "[{}] {} {} (x{}) — {}",
                time,
                match sev { Severity::Warning => "WARN", Severity::Normal => "OK" },
                reason, count, message,
            );
            (time, line)
        })
        .collect();
    related.sort_by_key(|(t, _)| *t);
    if related.len() > MAX_RELATED_LINES {
        let drop = related.len() - MAX_RELATED_LINES;
        related.drain(0..drop);
    }
    if related.is_empty() {
        None
    } else {
        Some(related.into_iter().map(|(_, l)| l).collect::<Vec<_>>().join("\n"))
    }
}

// Assemble the full prompt sent to the model: event metadata, object status, recent logs, related
// events, and enrichment sections. This is the complete payload transmitted to the AI endpoint.
// Rough char/token ratio for dense Kubernetes JSON, and tokens held back for the system prompt,
// the model's answer, and a safety margin. Used to derive a char budget from the context window.
const CHARS_PER_TOKEN_EST: usize = 3;
const COMPLETION_RESERVE_TOKENS: usize = 4096;

// Convert a provider context window (tokens) into a char budget for the whole user prompt.
fn prompt_char_budget(context_window: Option<usize>) -> Option<usize> {
    context_window
        .map(|toks| toks.saturating_sub(COMPLETION_RESERVE_TOKENS).saturating_mul(CHARS_PER_TOKEN_EST))
}

// Assemble the enrichment sections within `budget` chars, dropping the lowest-priority ones (later
// in the list) when the budget is exhausted and noting how many were omitted. At least the first
// (highest-priority) section is always included even if it alone exceeds the budget.
fn build_extra_block(extra: &[(String, String)], budget: Option<usize>) -> String {
    let st = lang::active();
    if extra.is_empty() { return st.prompt_none.to_string(); }
    let mut out = String::new();
    let mut omitted = 0;
    for (i, (title, body)) in extra.iter().enumerate() {
        let sep = if out.is_empty() { "" } else { "\n\n" };
        let section = format!("{sep}### {title}\n```json\n{body}\n```");
        if let Some(b) = budget {
            if !out.is_empty() && out.len() + section.len() > b {
                omitted = extra.len() - i;
                break;
            }
        }
        out.push_str(&section);
    }
    if omitted > 0 {
        out.push_str(&st.plural(
            omitted,
            st.prompt_sections_omitted_one,
            st.prompt_sections_omitted_many,
        ));
    }
    out
}

// Mirrors `build_ai_prompt_inner`'s parameters plus the budget; grouping them would only move the
// same list into a struct used at a single call site.
#[allow(clippy::too_many_arguments)]
fn build_ai_prompt(
    rec: &EventRecord,
    ctx_label: &str,
    ns_label: &str,
    logs: Option<&str>,
    status: Option<&str>,
    related: Option<&str>,
    extra: &[(String, String)],
    char_budget: Option<usize>,
) -> String {
    // Two-pass: render the skeleton with a placeholder for the enrichment block, measure the fixed
    // part, then fill the block with whatever fits in the remaining budget. With no enrichment at
    // all there is no placeholder to substitute and the section is dropped along with it.
    const PLACEHOLDER: &str = "\u{0}";
    let has_extra = !extra.is_empty();
    let ph = if has_extra { Some(PLACEHOLDER) } else { None };
    let skeleton = build_ai_prompt_inner(rec, ctx_label, ns_label, logs, status, related, ph);
    if !has_extra { return skeleton; }
    let fixed_len = skeleton.len() - PLACEHOLDER.len();
    let extra_budget = char_budget.map(|b| b.saturating_sub(fixed_len));
    let extra_block = build_extra_block(extra, extra_budget);
    skeleton.replace(PLACEHOLDER, &extra_block)
}

// Kept deliberately terse: every heading here is paid for on each analysis, and the model already
// has its instructions from the system prompt — repeating them in the request only costs tokens and
// nudges it towards finding something to say. Sections with nothing in them are not emitted at all.
fn build_ai_prompt_inner(
    rec: &EventRecord,
    ctx_label: &str,
    ns_label: &str,
    logs: Option<&str>,
    status: Option<&str>,
    related: Option<&str>,
    extra_block: Option<&str>,
) -> String {
    let mut out = format!(
"# Événement Kubernetes
cluster {ctx} · ns {ns_label}
{time} {sev} {reason} · {kind} {api} · {ns}/{name} · {comp} · x{count}
{msg}",
        ctx = ctx_label,
        ns_label = ns_label,
        time = rec.time,
        sev = match rec.severity { Severity::Warning => "Warning", Severity::Normal => "Normal" },
        reason = rec.reason,
        kind = rec.kind,
        api = rec.api_version,
        ns = rec.namespace,
        name = rec.name,
        comp = rec.component,
        count = rec.count,
        msg = rec.message,
    );
    for (title, body) in [
        ("## Statut", status),
        ("## Logs (200 dernières lignes)", logs),
        ("## Événements liés", related),
        ("## Contexte attaché", extra_block),
    ] {
        if let Some(body) = body {
            out.push_str(&format!("\n\n{title}\n{body}"));
        }
    }
    out.push_str("\n\n## Demande\nAnalyse ce contexte selon tes règles. Si des policies Kyverno ou des règles RBAC sont fournies, désigne la règle en cause et le patch minimal.");
    out
}

fn build_diag_doc(
    steps: &[DiagnosticStep],
    ai_content: &str,
    ai_error: Option<&str>,
    ai_model: &str,
) -> pdf::DiagDoc {
    let mut ok = 0; let mut warn = 0; let mut err = 0; let mut info = 0;
    for s in steps {
        match s.status {
            DiagStatus::Ok => ok += 1,
            DiagStatus::Warn => warn += 1,
            DiagStatus::Err => err += 1,
            DiagStatus::Info => info += 1,
            DiagStatus::Running => {}
        }
    }
    let pdf_steps: Vec<pdf::DiagStep> = steps
        .iter()
        .map(|s| pdf::DiagStep {
            status: match s.status {
                DiagStatus::Ok => "ok",
                DiagStatus::Warn => "warn",
                DiagStatus::Err => "err",
                DiagStatus::Info => "info",
                DiagStatus::Running => "info",
            },
            title: s.title.clone(),
            command: s.command.clone(),
            lines: s
                .lines
                .iter()
                .map(|(c, t)| pdf::DiagLine {
                    color: line_color_to_pdf(*c),
                    text: t.clone(),
                })
                .collect(),
        })
        .collect();

    pdf::DiagDoc {
        ok, warn, err, info,
        steps: pdf_steps,
        ai_model: ai_model.to_string(),
        ai_content: ai_content.to_string(),
        ai_error: ai_error.map(|s| s.to_string()),
    }
}

fn line_color_to_pdf(c: LineColor) -> &'static str {
    match c {
        LineColor::Plain => "plain",
        LineColor::Ok => "ok",
        LineColor::Warn => "warn",
        LineColor::Err => "err",
        LineColor::Info => "info",
        LineColor::Dim => "dim",
    }
}

// Un glyphe mal choisi décale toute la fin de sa ligne, et la bordure droite des panneaux part en
// escalier. Deux causes, mesurables toutes les deux, d'où les deux critères de la liste ci-dessous :
//   1. le glyphe doit exister dans la mono du terminal avec l'avance d'une cellule, sinon il est
//      dessiné depuis une police de repli proportionnelle (cosmic-term shape la ligne entière avec
//      cosmic-text, donc la dérive se propage jusqu'à la bordure) ;
//   2. il ne doit pas être couvert par la police emoji, sinon le moteur peut le détourner vers un
//      glyphe couleur double largeur — c'est ce qui arrivait au triangle U+25B6, remplacé par ►.
// Contrôles avant d'ajouter un glyphe (DejaVu Sans Mono = mono par défaut de la plupart des Linux) :
//     fc-list "DejaVu Sans Mono:charset=25CF" family   # vide = absent, à écarter
//     fc-list "Noto Color Emoji:charset=25CF" family   # non vide = risque emoji, à écarter
#[cfg(test)]
mod glyph_guard {
    // Vérifiés dans DejaVu Sans Mono (présents, avance 1233 = une cellule) et absents de Noto
    // Color Emoji.
    const APPROVED: &str = "²·«»×–—•…←↑→↓↡↻⇅≥⊞⊟⊡─│└═█▏░■▲▸►▼▾◂○●◐◑◒◓◔✓✗";

    #[test]
    fn sources_use_only_font_safe_glyphs() {
        let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
        let mut offenders: Vec<String> = Vec::new();
        for entry in std::fs::read_dir(&dir).expect("src/ illisible") {
            let path = entry.expect("entrée de src/ illisible").path();
            if path.extension().and_then(|e| e.to_str()) != Some("rs") {
                continue;
            }
            let src = std::fs::read_to_string(&path).expect("source illisible");
            let name = path.file_name().unwrap_or_default().to_string_lossy().to_string();
            for ch in src.chars() {
                // Les lettres accentuées viennent du texte FR/EN, pas de l'iconographie.
                if ch.is_ascii() || ch.is_alphabetic() || APPROVED.contains(ch) {
                    continue;
                }
                let found = format!("{name}: {ch} (U+{:04X})", ch as u32);
                if !offenders.contains(&found) {
                    offenders.push(found);
                }
            }
        }
        assert!(
            offenders.is_empty(),
            "glyphes hors liste, potentiellement absents de la police mono du terminal : {}",
            offenders.join(", ")
        );
    }
}

#[cfg(test)]
mod popup_tests {
    use super::*;

    #[test]
    fn a_line_of_long_words_wraps_wider_than_a_plain_division() {
        // 24 characters over a width of 10: the division says 3 rows, but no break fits before
        // column 10, so it really takes 4. Under-counting here is what pushes a prompt off-screen.
        let line = Line::from("flux-system/kustomize-cx");
        assert_eq!(line.width(), 24);
        assert_eq!(line.width().div_ceil(10), 3);
        assert_eq!(wrapped_rows(&line, 10), 3, "one word longer than the width breaks mid-word");

        let line = Line::from("aaaaaa bbbbbb cccccc");
        assert_eq!(line.width().div_ceil(10), 2);
        assert_eq!(wrapped_rows(&line, 10), 3, "words never straddle two rows");
    }

    #[test]
    fn wrapping_keeps_whole_words_and_breaks_only_what_cannot_fit() {
        assert_eq!(wrap_text("un deux trois", 9), vec!["un deux", "trois"]);
        // A word longer than the line is the one case that breaks mid-word.
        assert_eq!(wrap_text("abcdefghij", 4), vec!["abcd", "efgh", "ij"]);
        assert_eq!(wrap_text("", 10), vec![""]);
    }

    #[test]
    fn an_empty_line_still_takes_a_row() {
        assert_eq!(wrapped_rows(&Line::from(""), 20), 1);
        assert_eq!(wrapped_rows(&Line::from("short"), 20), 1);
    }
}

#[cfg(test)]
mod palette_tests {
    use super::*;

    // Enter runs the highlighted suggestion, so the first entry *is* what a typed word does. A word
    // that is one command's exact alias must never be beaten by another whose alias merely starts
    // with it — `pvc` belongs to `storage`, and `pv` is a command of its own.
    #[test]
    fn exact_match_outranks_prefix_match() {
        assert_eq!(command_name_suggestions("pv").first(), Some(&"pv"));
        assert_eq!(command_name_suggestions("pvc").first(), Some(&"storage"));
        assert_eq!(command_name_suggestions("storage").first(), Some(&"storage"));
        assert_eq!(command_name_suggestions("sc").first(), Some(&"pv"));
        assert_eq!(command_name_suggestions("ns").first(), Some(&"namespace"));
    }

    // Prefix completion still works where nothing matches exactly, and both storage worlds stay
    // reachable from the words that describe them.
    #[test]
    fn prefix_completion_still_offers_both_storage_worlds() {
        let stock = command_name_suggestions("stock");
        assert_eq!(stock, vec!["storage"]);
        let sto = command_name_suggestions("storagec");
        assert_eq!(sto, vec!["pv"]);
        assert_eq!(resolve_command("volumes"), Some("storage"));
        assert_eq!(resolve_command("persistentvolume"), Some("pv"));
    }

    // The three velero entries share a prefix on purpose — `backup` opens the view, and every
    // `backup*` location word opens it on the locations. Each has to keep landing on its own world.
    #[test]
    fn the_velero_words_land_on_their_own_world() {
        assert_eq!(command_name_suggestions("backup").first(), Some(&"velero"));
        assert_eq!(command_name_suggestions("backups").first(), Some(&"velero"));
        assert_eq!(command_name_suggestions("bsl").first(), Some(&"bsl"));
        assert_eq!(command_name_suggestions("restore").first(), Some(&"restores"));
        assert_eq!(resolve_command("schedules"), Some("velero"));
        assert_eq!(resolve_command("backuprepositories"), Some("bsl"));
        // `backupstoragelocation` starts with `backup`, which is velero's exact alias; the exact
        // match still has to win for the shorter word and the longer one must reach the locations.
        assert_eq!(resolve_command("backupstoragelocation"), Some("bsl"));
    }

    // Every view whose rows are namespaced objects takes a `<ns>` argument, whichever word was typed
    // to reach it: `:configmap kube-system` has to scope the view, not be swallowed silently.
    #[test]
    fn the_namespaced_views_take_a_namespace_argument() {
        for word in [
            "configmap", "cm", "secret", "certificates", "svc", "ingress", "netpol", "pvc",
            "resourcequota", "vulnerabilities", "backups", "restore", "medusabackup", "pods",
            "deployments", "rbac", "roles", "bindings",
        ] {
            let cmd = resolve_command(word).unwrap_or_else(|| panic!("{word} resolves to nothing"));
            assert!(command_takes_ns(cmd), "{word} -> {cmd} refuses a namespace");
        }
    }

    // The cluster-scoped views must keep refusing it: an argument that cannot narrow anything would
    // be accepted and then do nothing, which is worse than a typo.
    #[test]
    fn the_cluster_scoped_views_refuse_one() {
        for word in ["nodes", "capacity", "pv", "rancher", "argocd", "flux", "reflector", "kyverno"] {
            let cmd = resolve_command(word).unwrap_or_else(|| panic!("{word} resolves to nothing"));
            assert!(!command_takes_ns(cmd), "{word} -> {cmd} accepts a namespace it cannot apply");
        }
    }

    // `all`, `*` and `0` are the three ways to say "every namespace" — the palette maps them to the
    // same unscoped watcher the `0` key gives.
    #[test]
    fn the_all_namespaces_words_clear_the_scope() {
        assert_eq!(ns_arg_to_opt("all"), None);
        assert_eq!(ns_arg_to_opt("*"), None);
        assert_eq!(ns_arg_to_opt("0"), None);
        assert_eq!(ns_arg_to_opt("kube-system"), Some("kube-system".to_string()));
    }
}

#[cfg(test)]
mod velero_view_tests {
    use super::*;

    fn backup(name: &str) -> VelRow {
        VelRow::Backup(Box::new(VelBackup {
            uid: format!("vel|backup|velero/{}", name),
            namespace: "velero".to_string(),
            name: name.to_string(),
            ..VelBackup::default()
        }))
    }

    fn ct_ns(uid: &str, ns: &str) -> VelRow {
        VelRow::CtNs {
            backup_uid: uid.to_string(),
            namespace: ns.to_string(),
            objects: 1,
            kinds: 1,
        }
    }

    fn ct_object(ns: &str, name: &str) -> VelRow {
        VelRow::CtObject {
            api_version: "v1".to_string(),
            kind: "ConfigMap".to_string(),
            namespace: ns.to_string(),
            name: name.to_string(),
        }
    }

    #[test]
    fn a_matched_object_keeps_the_rows_it_hangs_from() {
        // `/nginx` matching a ConfigMap deep inside a backup must not leave it floating: without the
        // namespace and the backup above it, the match names an object and says nothing about where
        // it came from — which is the only reason one was looking.
        let uid = "vel|backup|velero/daily-1";
        let rows = vec![
            backup("daily-1"),
            ct_ns(uid, "prod"),
            VelRow::CtKind {
                backup_uid: uid.to_string(),
                namespace: "prod".to_string(),
                kind: "ConfigMap".to_string(),
                objects: 2,
            },
            ct_object("prod", "nginx-conf"),
            ct_object("prod", "other"),
        ];
        let mut keep = vec![false, false, false, true, false];
        vel_keep_ancestors(&rows, &mut keep);
        assert_eq!(keep, vec![true, true, true, true, false]);
    }

    #[test]
    fn a_folded_branch_is_not_an_ancestor_of_the_next_one() {
        // Two backups side by side: a match under the second must not drag the first one's namespace
        // back on screen just because it was the most recent row at that depth.
        let (a, b) = ("vel|backup|velero/a", "vel|backup|velero/b");
        let rows = vec![
            backup("a"),
            ct_ns(a, "prod"),
            backup("b"),
            ct_ns(b, "staging"),
        ];
        let mut keep = vec![false, false, false, true];
        vel_keep_ancestors(&rows, &mut keep);
        assert_eq!(keep, vec![false, false, true, true]);
    }

    fn form(namespaces: &[(&str, bool)], kinds: &[(&str, bool)]) -> VelRestoreView {
        VelRestoreView {
            namespace: "velero".to_string(),
            backup: "daily-1".to_string(),
            namespaces: namespaces.iter().map(|(n, on)| (n.to_string(), *on)).collect(),
            kinds: kinds
                .iter()
                .map(|(k, on)| ("v1".to_string(), k.to_string(), *on))
                .collect(),
            manual_namespaces: false,
            ns_text: String::new(),
            target_ns: String::new(),
            labels: String::new(),
            overwrite: false,
            cursor: 0,
            scroll: 0,
            editing: false,
            armed: false,
            typed: None,
        }
    }

    #[test]
    fn a_target_namespace_needs_exactly_one_source() {
        // Velero maps namespace by namespace. With two sources ticked there is no single source to
        // map from, and quietly mapping one of them would send half the restore somewhere the user
        // never asked for.
        let mut v = form(&[("prod", true), ("staging", true)], &[]);
        v.target_ns = "restore-here".to_string();
        assert_eq!(v.options_without_resources().namespace_mapping, None);

        v.namespaces[1].1 = false;
        assert_eq!(
            v.options_without_resources().namespace_mapping,
            Some(("prod".to_string(), "restore-here".to_string()))
        );
        // Mapping a namespace onto itself is what velero does by default; saying it twice adds
        // nothing to the spec.
        v.target_ns = "prod".to_string();
        assert_eq!(v.options_without_resources().namespace_mapping, None);
    }

    #[test]
    fn every_kind_ticked_means_no_kind_filter() {
        // An `includedResources` listing every kind of the backup is not the same spec as no filter
        // at all: it also excludes anything the inventory did not mention, which for a backup still
        // running is a moving target.
        let v = form(&[("prod", true)], &[("ConfigMap", true), ("Secret", true)]);
        assert!(v.kinds_to_resolve().is_empty());

        let v = form(&[("prod", true)], &[("ConfigMap", true), ("Secret", false)]);
        assert_eq!(
            v.kinds_to_resolve(),
            vec![("v1".to_string(), "ConfigMap".to_string())]
        );
    }

    #[test]
    fn typed_namespaces_are_split_and_trimmed() {
        // The fallback path, used exactly when the inventory could not be downloaded — which on an
        // in-cluster MinIO is the common case, not the exotic one.
        let mut v = form(&[], &[]);
        v.manual_namespaces = true;
        v.ns_text = " prod , , staging ".to_string();
        assert_eq!(v.selected_namespaces(), vec!["prod", "staging"]);
    }

    #[test]
    fn a_label_selector_ignores_what_is_not_a_pair() {
        let mut v = form(&[("prod", true)], &[]);
        v.labels = "app=web, broken ,tier=front,=novalue".to_string();
        assert_eq!(
            v.parsed_labels(),
            vec![
                ("app".to_string(), "web".to_string()),
                ("tier".to_string(), "front".to_string())
            ]
        );
    }
}

// The three depths of the workloads view, rendered for real: a container row must line its columns
// up under the pod's and must not push the table past its own frame.
#[cfg(test)]
mod pods_container_rows_tests {
    use super::*;
    use crate::pods::OwnerRef;
    use ratatui::backend::TestBackend;
    use ratatui::Terminal;

    fn pod(name: &str, containers: Vec<ContainerResource>) -> PodResource {
        PodResource {
            namespace: "kube-system".to_string(),
            name: name.to_string(),
            ready: "1/2".to_string(),
            status: "Running".to_string(),
            restarts: 3,
            age: "12d".to_string(),
            node: "aks-pool-000000".to_string(),
            ip: "10.244.3.17".to_string(),
            owner: Some(OwnerRef {
                kind: "Deployment".to_string(),
                name: "konnectivity-agent".to_string(),
                namespace: "kube-system".to_string(),
                api_version: "apps/v1".to_string(),
            }),
            uid: format!("pod|kube-system/{}", name),
            cpu_milli: Some(120),
            mem_bytes: Some(300 * 1024 * 1024),
            cpu_req: Some(100),
            cpu_lim: Some(500),
            mem_req: Some(256 * 1024 * 1024),
            mem_lim: Some(512 * 1024 * 1024),
            containers,
        }
    }

    fn ctr(name: &str, kind: ContainerKind, state: &str, ready: bool) -> ContainerResource {
        ContainerResource {
            namespace: "kube-system".to_string(),
            pod: "konnectivity-agent-7d9f".to_string(),
            name: name.to_string(),
            image: "mcr.microsoft.com/oss/kubernetes/apiserver-network-proxy/agent:v0.30.3".to_string(),
            kind,
            ready,
            state: state.to_string(),
            restarts: 2,
            age: "4h".to_string(),
            cpu_milli: Some(60),
            mem_bytes: Some(150 * 1024 * 1024),
            cpu_req: Some(60),
            cpu_lim: Some(120),
            mem_req: Some(300 * 1024 * 1024),
            mem_lim: Some(600 * 1024 * 1024),
            uid: ContainerResource::uid("kube-system", "konnectivity-agent-7d9f", name),
        }
    }

    fn workload() -> WorkloadResource {
        WorkloadResource {
            kind: "Deployment".to_string(),
            api_version: "apps/v1".to_string(),
            namespace: "kube-system".to_string(),
            name: "konnectivity-agent".to_string(),
            replicas: Some(2),
            ready_replicas: 2,
            desired: None,
            job: None,
            age: "30d".to_string(),
            uid: WorkloadResource::uid("Deployment", "kube-system", "konnectivity-agent"),
        }
    }

    fn expanded_rows() -> Vec<PodRow> {
        let containers = vec![
            ctr("init-certs", ContainerKind::Init, "Completed", false),
            ctr("agent", ContainerKind::Regular, "Running", true),
            ctr("debugger", ContainerKind::Ephemeral, "CrashLoopBackOff", false),
        ];
        let p = pod("konnectivity-agent-7d9f", containers.clone());
        let mut rows = vec![PodRow::Workload(workload()), PodRow::Pod(Box::new(p))];
        rows.extend(containers.into_iter().map(|c| PodRow::Container(Box::new(c))));
        rows
    }

    fn render(rows: &[PodRow], expanded: &std::collections::HashSet<String>, width: u16) -> Vec<String> {
        let (table_rows, widths) = pods_table_parts(rows, true, expanded, width);
        let mut terminal = Terminal::new(TestBackend::new(width, 12)).expect("test terminal");
        terminal
            .draw(|f| {
                let t = Table::new(table_rows, widths)
                    .header(header_row())
                    .block(Block::default().borders(Borders::ALL).title("workloads"));
                f.render_widget(t, f.area());
            })
            .expect("draw");
        let buffer = terminal.backend().buffer().clone();
        (0..12)
            .map(|y| {
                (0..width)
                    .map(|x| buffer.cell((x, y)).expect("cell").symbol().to_string())
                    .collect::<String>()
            })
            .collect()
    }

    #[test]
    fn a_container_row_shows_its_own_state_readiness_and_restart_age() {
        let rows = expanded_rows();
        let expanded: std::collections::HashSet<String> =
            std::iter::once("pod|kube-system/konnectivity-agent-7d9f".to_string()).collect();
        let text = render(&rows, &expanded, 190).join("\n");
        // Unfolded, the pod says so; the three families are told apart by their prefix.
        assert!(text.contains("▾ konnectivity-agent-7d9f"), "{text}");
        assert!(text.contains("· init:init-certs"), "{text}");
        assert!(text.contains("· agent"), "{text}");
        assert!(text.contains("· eph:debugger"), "{text}");
        // Each container carries its own state, not the pod's. STATUS is 12 cells wide, as it has
        // always been for pods, so the long reasons read truncated here too.
        assert!(text.contains("Completed"), "{text}");
        assert!(text.contains("CrashLoopBac"), "{text}");
        // The percentages are the container's own usage against the container's own requests and
        // limits — 60m of a 60m request and a 120m limit — not a copy of the pod's line.
        let ctr_line = text
            .lines()
            .find(|l| l.contains("· agent"))
            .expect("the container line");
        assert!(ctr_line.contains("100%") && ctr_line.contains("50%"), "{ctr_line}");
        assert!(ctr_line.contains("25%"), "{ctr_line}");
        // The pod's node and IP are not repeated on the container lines.
        assert_eq!(text.matches("10.244.3.17").count(), 1, "{text}");
        assert_eq!(text.matches("aks-pool-000000").count(), 1, "{text}");
    }

    #[test]
    fn a_node_name_too_long_for_its_column_keeps_its_head_and_its_tail() {
        // Two pods of the same nodepool: only the suffix tells their nodes apart, so an
        // end-truncated column would print the same string twice.
        let mut p1 = pod("konnectivity-agent-7d9f", vec![]);
        p1.node = "aks-systempool-41894869-vmss000003".to_string();
        let mut p2 = pod("konnectivity-agent-8a1c", vec![]);
        p2.node = "aks-systempool-41894869-vmss000017".to_string();
        let rows = vec![
            PodRow::Workload(workload()),
            PodRow::Pod(Box::new(p1)),
            PodRow::Pod(Box::new(p2)),
        ];
        let expanded = std::collections::HashSet::new();
        // Wide enough: the column grows to the names instead of leaving the space empty.
        let wide = render(&rows, &expanded, 190);
        let text = wide.join("\n");
        assert!(text.contains("aks-systempool-41894869-vmss000003"), "{text}");
        assert!(text.contains("aks-systempool-41894869-vmss000017"), "{text}");
        // Narrow enough that the column caps at what is left: head and tail both survive.
        let narrow = render(&rows, &expanded, 171);
        let text = narrow.join("\n");
        assert!(text.contains("aks-systempo…9-vmss000003"), "{text}");
        assert!(text.contains("aks-systempo…9-vmss000017"), "{text}");
        // Neither width shears the right border: every body line still closes on `│`, and the
        // corners of the top and bottom rules stay in the last column.
        for lines in [&wide, &narrow] {
            for line in lines.iter().skip(1).take(lines.len() - 2) {
                assert!(line.ends_with('│'), "{line}");
            }
            for rule in [lines.first().expect("top"), lines.last().expect("bottom")] {
                assert!(!rule.ends_with(' '), "{rule}");
            }
        }
    }

    #[test]
    fn a_folded_pod_advertises_the_containers_without_listing_them() {
        let rows = vec![
            PodRow::Workload(workload()),
            PodRow::Pod(Box::new(pod(
                "konnectivity-agent-7d9f",
                vec![ctr("agent", ContainerKind::Regular, "Running", true)],
            ))),
        ];
        let text = render(&rows, &std::collections::HashSet::new(), 190).join("\n");
        assert!(text.contains("▸ konnectivity-agent-7d9f"), "{text}");
        assert!(!text.contains("· agent"), "folded, so no container line: {text}");
    }

    // The rule this codebase has been bitten by: a wider NAME column (the fold marker adds two
    // cells, the container prefix four) must not push the table through its own right border.
    #[test]
    fn the_right_border_survives_every_width() {
        let rows = expanded_rows();
        let expanded: std::collections::HashSet<String> =
            std::iter::once("pod|kube-system/konnectivity-agent-7d9f".to_string()).collect();
        let border = ratatui::symbols::border::PLAIN;
        for width in [60_u16, 100, 140, 190, 196] {
            let lines = render(&rows, &expanded, width);
            for (y, line) in lines.iter().enumerate() {
                let last = line.chars().last().expect("a rendered line");
                let expected = match y {
                    0 => border.top_right,
                    11 => border.bottom_right,
                    _ => border.vertical_right,
                };
                assert_eq!(
                    last.to_string(),
                    expected,
                    "right border eaten at width {width}, row {y}: {line}"
                );
            }
        }
    }
}

#[cfg(test)]
mod k8c_snapshot_panel_tests {
    use super::*;
    use crate::k8ssandra::SnapshotTag;
    use ratatui::backend::TestBackend;
    use ratatui::Terminal;

    const NOW: i64 = 1_700_000_000;

    fn tags() -> Vec<SnapshotTag> {
        vec![
            SnapshotTag {
                tag: "truncated-1699913600000-events_by_device_and_a_long_table".to_string(),
                keyspaces: vec!["app".to_string(), "app_history".to_string()],
                tables: 214,
                true_bytes: Some(12.0 * 1024.0_f64.powi(3)),
                disk_bytes: Some(13.0 * 1024.0_f64.powi(3)),
                partial: true,
                created: Some(NOW - 86_400),
            },
            SnapshotTag {
                tag: "medusa-2026-08-12".to_string(),
                keyspaces: vec!["app".to_string()],
                tables: 12,
                true_bytes: Some(1024.0),
                disk_bytes: Some(2048.0),
                partial: false,
                created: None,
            },
        ]
    }

    #[test]
    fn a_tag_says_what_it_holds_since_when_and_where_it_came_from() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let text: Vec<String> = k8c_snapshot_lines(&tags(), NOW, st)
            .iter()
            .map(|l| l.spans.iter().map(|s| s.content.to_string()).collect())
            .collect();
        let joined = text.join("\n");
        assert!(joined.contains("214 tables"), "{joined}");
        assert!(joined.contains("app, app_history"), "{joined}");
        assert!(joined.contains("1d"), "the age of the tag: {joined}");
        assert!(joined.contains(st.k8c_snap_origin_truncate), "{joined}");
        // The two sizes together, never the on-disk one alone: a snapshot is hard links, and most of
        // what it weighs is still shared with the live sstables and frees nothing.
        assert!(joined.contains(st.k8c_snap_reclaimable_short), "{joined}");
        assert!(joined.contains("13.0 GiB"), "the on-disk size is shown too: {joined}");
        assert!(joined.contains(st.k8c_snap_shared), "{joined}");
        // A Medusa tag standing after its run is a fact worth naming: Medusa clears its own.
        assert!(joined.contains(st.k8c_snap_origin_medusa), "{joined}");
        // A sum missing a file is a floor, said out loud rather than passed off as a total.
        assert!(joined.contains("≥ 12.0 GiB"), "{joined}");
        assert!(joined.contains(st.k8c_snap_partial), "{joined}");
        // Nothing is invented for the tag Cassandra did not name and did not date.
        assert!(joined.contains(st.k8c_snap_no_date), "{joined}");
    }

    // The rule this view has been bitten by: a detail line that runs past the frame eats the right
    // border. Rendered here at the widths a real terminal produces, including the narrow one.
    #[test]
    fn the_right_border_survives_every_width() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        for width in [40_u16, 60, 100, 196] {
            let mut terminal =
                Terminal::new(TestBackend::new(width, 24)).expect("test terminal");
            terminal
                .draw(|f| {
                    let p = Paragraph::new(k8c_snapshot_lines(&tags(), NOW, st))
                        .wrap(Wrap { trim: false })
                        .block(Block::default().borders(Borders::ALL).title(" k8ssandra "));
                    f.render_widget(p, f.area());
                })
                .expect("draw");
            let buffer = terminal.backend().buffer().clone();
            // Compared against ratatui's own border set rather than against glyphs typed here: the
            // corners are not part of this codebase's approved iconography.
            let border = ratatui::symbols::border::PLAIN;
            for y in 0..24 {
                let cell = buffer.cell((width - 1, y)).expect("right column");
                let expected = match y {
                    0 => border.top_right,
                    23 => border.bottom_right,
                    _ => border.vertical_right,
                };
                assert_eq!(
                    cell.symbol(),
                    expected,
                    "right border eaten at width {width}, row {y}"
                );
            }
        }
    }
}

#[cfg(test)]
mod portfwd_view_tests {
    use super::*;
    use ratatui::backend::TestBackend;
    use ratatui::Terminal;

    fn row(local: u16, state: PfState) -> PfRow {
        PfRow {
            id: 1,
            namespace: "apps".to_string(),
            service: "web".to_string(),
            service_port: 80,
            port_name: Some("http".to_string()),
            local_port: local,
            pod: "web-7c9d5f8b6d-x2klm".to_string(),
            remote_port: 8080,
            state,
            open: 2,
            served: 14,
            last_error: None,
        }
    }

    #[test]
    fn the_column_says_nothing_about_a_service_nobody_forwards() {
        let (txt, _) = forward_cell(&[]);
        assert!(txt.is_empty(), "an unforwarded Service gets a blank cell, not a dash: {txt:?}");
    }

    #[test]
    fn the_column_names_the_local_port_and_counts_the_others() {
        let (txt, color) = forward_cell(&[row(18080, PfState::Listening)]);
        assert_eq!(txt, "→ :18080");
        assert_eq!(color, Color::Green);
        let (txt, _) = forward_cell(&[row(18080, PfState::Listening), row(18443, PfState::Listening)]);
        assert_eq!(txt, "→ :18080 +1", "the second forward is counted, not hidden");
    }

    // A forward that failed keeps its row: the cell has to show it, or the only trace of a port
    // that never opened is a toast that has already scrolled away.
    #[test]
    fn a_failed_forward_colours_the_column_even_next_to_a_live_one() {
        let failed = row(18080, PfState::Failed("address already in use".to_string()));
        let (_, color) = forward_cell(&[row(18443, PfState::Listening), failed]);
        assert_eq!(color, Color::Red);
        let (_, color) = forward_cell(&[row(18080, PfState::Starting)]);
        assert_eq!(color, Color::Yellow, "starting is not yet listening");
    }

    fn view() -> PfView {
        PfView {
            namespace: "apps".to_string(),
            service: "web".to_string(),
            ports: vec![
                SvcPortSpec {
                    name: Some("http".to_string()),
                    port: 80,
                    protocol: "TCP".to_string(),
                    target: "8080".to_string(),
                },
                SvcPortSpec {
                    name: Some("metrics".to_string()),
                    port: 9090,
                    protocol: "TCP".to_string(),
                    target: "metrics".to_string(),
                },
            ],
            locals: vec!["80".to_string(), "9090".to_string()],
            cursor: 0,
            error: None,
        }
    }

    fn text(lines: &[Line]) -> String {
        lines
            .iter()
            .map(|l| l.spans.iter().map(|s| s.content.as_ref()).collect::<String>())
            .collect::<Vec<_>>()
            .join("\n")
    }

    // The rule this project holds to for any prompt: the field is visible, with the value it will
    // use, before a single digit is typed.
    #[test]
    fn the_form_shows_every_port_with_the_local_port_it_would_take() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let v = view();
        let joined = text(&pf_form_lines(&v, &[None, None], st));
        assert!(joined.contains("80/TCP (http)"), "{joined}");
        assert!(joined.contains("→ 8080"), "the target port is named: {joined}");
        assert!(joined.contains("→ metrics"), "a named targetPort is shown as named: {joined}");
        assert!(joined.contains(st.pf_local_label), "{joined}");
        assert!(joined.contains("9090"), "{joined}");
    }

    // A port already forwarded must not offer a field: the same Enter stops it, and the line says
    // where it is listening instead of pretending a new one can be typed.
    #[test]
    fn a_forwarded_port_shows_where_it_listens_instead_of_a_field() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let v = view();
        let lines = pf_form_lines(&v, &[Some(row(18080, PfState::Listening)), None], st);
        let first: String = lines[0].spans.iter().map(|s| s.content.as_ref()).collect();
        assert!(first.contains("127.0.0.1:18080"), "{first}");
        assert!(first.contains(st.pf_state_listening), "{first}");
        assert!(!first.contains(st.pf_local_label), "no field on a live forward: {first}");
    }

    #[test]
    fn the_list_names_the_pod_the_service_landed_on() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let joined = text(&pf_list_lines(&[row(18080, PfState::Listening)], 0, st));
        assert!(joined.contains("127.0.0.1:18080"), "{joined}");
        assert!(joined.contains("apps/web:80 (http)"), "{joined}");
        // The pod and its port: a Service forward lands on one replica, and the list is where that
        // is admitted.
        assert!(joined.contains("web-7c9d5f8b6d-x2klm:8080"), "{joined}");
        assert!(joined.contains("14"), "the connection counters: {joined}");
    }

    // The regression this split fixed: the state carried the whole toast sentence, so the row read
    // "failed: ✗ port-forward: local port 8000 unusable" — the reason twice over, once decorated.
    #[test]
    fn a_failed_forward_states_its_cause_once_and_counts_nothing() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let failed = PfRow {
            state: PfState::Failed("port local 8000 inutilisable (Address in use)".to_string()),
            open: 0,
            served: 0,
            ..row(8000, PfState::Listening)
        };
        let joined = text(&pf_list_lines(&[failed], 0, st));
        assert_eq!(joined.matches("port local 8000 inutilisable").count(), 1, "{joined}");
        assert!(joined.contains(st.pf_state_failed), "{joined}");
        assert!(!joined.contains("servie"), "no counters on a forward that never opened: {joined}");
    }

    #[test]
    fn an_empty_list_says_so_rather_than_showing_an_empty_frame() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let joined = text(&pf_list_lines(&[], 0, st));
        assert!(joined.contains(st.pf_list_empty), "{joined}");
    }

    // Both overlays are text panels inside a bordered block: the rule that has bitten every other
    // one of them applies here too.
    #[test]
    fn the_right_border_survives_every_width() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let v = view();
        let long = PfRow {
            state: PfState::Failed("address already in use, and a long explanation after it".to_string()),
            ..row(18080, PfState::Listening)
        };
        let panels = [
            pf_form_lines(&v, &[Some(row(18080, PfState::Listening)), None], st),
            pf_list_lines(&[long, row(18443, PfState::Starting)], 1, st),
        ];
        for lines in panels {
            for width in [40_u16, 60, 100, 196] {
                let mut terminal = Terminal::new(TestBackend::new(width, 24)).expect("test terminal");
                terminal
                    .draw(|f| {
                        let p = Paragraph::new(lines.clone())
                            .wrap(Wrap { trim: false })
                            .block(Block::default().borders(Borders::ALL).title(" port-forward "));
                        f.render_widget(p, f.area());
                    })
                    .expect("draw");
                let buffer = terminal.backend().buffer().clone();
                let border = ratatui::symbols::border::PLAIN;
                for y in 0..24 {
                    let cell = buffer.cell((width - 1, y)).expect("right column");
                    let expected = match y {
                        0 => border.top_right,
                        23 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(
                        cell.symbol(),
                        expected,
                        "right border eaten at width {width}, row {y}"
                    );
                }
            }
        }
    }
}

#[cfg(test)]
mod table_scroll_tests {
    use super::*;

    // Walking back up must move the cursor inside the window, not slide the whole list down under a
    // cursor stuck on the last row — the shape a `TableState` rebuilt at every frame produces.
    #[test]
    fn a_table_scrolls_only_at_its_edges() {
        use ratatui::backend::TestBackend;
        use ratatui::Terminal;
        const W: u16 = 20;
        const H: u16 = 10;
        // Borders take one row top and bottom: eight rows are on screen.
        const VISIBLE: usize = H as usize - 2;
        let mut terminal = Terminal::new(TestBackend::new(W, H)).expect("test terminal");
        let mut draw = |cursor: usize, offset: &mut usize| {
            terminal
                .draw(|f| {
                    let rows: Vec<Row> =
                        (0..100).map(|i| Row::new(vec![Cell::from(i.to_string())])).collect();
                    let table = Table::new(rows, [Constraint::Min(4)])
                        .block(Block::default().borders(Borders::ALL));
                    render_table_keep_offset(f, table, f.area(), Some(cursor), offset);
                })
                .expect("draw");
        };

        let mut offset = 0usize;
        draw(0, &mut offset);
        assert_eq!(offset, 0);
        draw(VISIBLE - 1, &mut offset);
        assert_eq!(offset, 0, "the cursor walks the visible rows without scrolling");
        draw(20, &mut offset);
        assert_eq!(offset, 20 - VISIBLE + 1, "past the bottom edge the list scrolls by what it must");
        draw(19, &mut offset);
        assert_eq!(offset, 20 - VISIBLE + 1, "coming back up the list stays put: the cursor moves");
        draw(13, &mut offset);
        assert_eq!(offset, 13, "still put down to the top row of the window");
        draw(12, &mut offset);
        assert_eq!(offset, 12, "and only then does it scroll, by one row");
    }
}

#[cfg(test)]
mod flux_view_tests {
    use super::*;

    fn res(kind: &str, prune: Option<bool>, suspended: bool) -> FluxResource {
        FluxResource {
            kind: kind.to_string(),
            api_version: "kustomize.toolkit.fluxcd.io/v1".to_string(),
            namespace: "flux-system".to_string(),
            name: "apps".to_string(),
            ready: FluxReady::Ready,
            suspended,
            message: "Applied revision main@sha1:abc".to_string(),
            revision: String::new(),
            age: String::new(),
            source_ref: None,
            depends_on: Vec::new(),
            prune,
            helm_chart: None,
        }
    }

    #[test]
    fn only_a_kustomization_that_keeps_its_objects_is_badged() {
        assert_eq!(prune_badge(Some(false)), NO_PRUNE_BADGE);
        // Pruning is the norm: nothing to say about it, and nothing to say about the kinds that have
        // no spec.prune in the first place.
        assert_eq!(prune_badge(Some(true)), "");
        assert_eq!(prune_badge(None), "");
    }

    fn win_text(line: &Line) -> String {
        line.spans.iter().map(|s| s.content.as_ref()).collect()
    }

    #[test]
    fn the_focused_row_pans_its_message_instead_of_growing_taller() {
        let mut r = res("Kustomization", None, false);
        r.message = "abcdefghijklmnopqrstuvwxyz".to_string();
        let line = flux_message_line(&r, Color::White);
        let w = 10;

        let head = win_text(&line_window(&line, 0, w));
        assert_eq!(head, "abcdefghi…", "the cut side is marked and the window fills the column exactly");
        assert_eq!(head.chars().count(), w);

        // The bound has to pay for the left marker, or the last characters are never reachable.
        let tail = win_text(&line_window(&line, msg_max_offset(flux_message_len(&r), w), w));
        assert!(tail.starts_with('…'), "the text left behind is marked too");
        assert!(tail.ends_with('z'), "the end of the message is reachable: {tail}");
        assert!(tail.chars().count() <= w);

        // An offset past the end of the text is a window, not a panic.
        assert!(win_text(&line_window(&line, 999, w)).chars().count() <= w);
        assert_eq!(win_text(&line_window(&line, 0, 0)), "");
    }

    fn render_table(resources: &[FluxResource], selected: usize, msg_scroll: usize, width: u16) -> Vec<String> {
        use ratatui::backend::TestBackend;
        use ratatui::Terminal;
        const H: u16 = 10;
        let (rows, widths, _) =
            flux_table_parts(resources, Some(selected), msg_scroll, width);
        let mut state = TableState::default();
        state.select(Some(selected));
        let mut terminal = Terminal::new(TestBackend::new(width, H)).expect("test terminal");
        terminal
            .draw(|f| {
                let t = Table::new(rows, widths)
                    .header(flux_header_row())
                    .block(Block::default().borders(Borders::ALL).title("flux"))
                    .row_highlight_style(Style::default().bg(SELECTED_BG))
                    .highlight_symbol("> ");
                f.render_stateful_widget(t, f.area(), &mut state);
            })
            .expect("draw");
        let buffer = terminal.backend().buffer().clone();
        (0..H)
            .map(|y| {
                (0..width)
                    .map(|x| buffer.cell((x, y)).expect("cell").symbol().to_string())
                    .collect::<String>()
            })
            .collect()
    }

    fn long_message_set() -> Vec<FluxResource> {
        let mut failed = res("Kustomization", Some(false), false);
        failed.ready = FluxReady::Failed;
        failed.message = "Kustomize build failed: accumulating resources from '../../base/app': \
            evalsymlink failure on '/tmp/kustomization-1234/base/app' : lstat: no such file"
            .to_string();
        vec![res("GitRepository", None, false), failed, res("HelmRelease", None, true)]
    }

    // The bug this replaced: the focused row grew several lines tall and reflowed the table under
    // the cursor. Every row is one line now, whatever the message and wherever the pan sits.
    #[test]
    fn the_focused_row_never_takes_more_than_one_line() {
        let resources = long_message_set();
        for scroll in [0_usize, 20, 400] {
            let lines = render_table(&resources, 1, scroll, 140);
            // Header on row 1, then one row per resource — the fourth is already blank.
            assert!(lines[2].contains("GitRepository"), "{}", lines[2]);
            assert!(lines[3].contains("Kustomization"), "row {scroll}: {}", lines[3]);
            assert!(lines[4].contains("HelmRelease"), "row {scroll}: {}", lines[4]);
            assert!(lines[3].starts_with("│> "), "the cursor sits on one row only: {}", lines[3]);
        }
    }

    #[test]
    fn panning_the_focused_row_walks_the_message_without_touching_the_right_border() {
        let resources = long_message_set();
        let border = ratatui::symbols::border::PLAIN;
        for width in [60_u16, 100, 140, 190, 196] {
            for scroll in [0_usize, 15, 60, 400] {
                let lines = render_table(&resources, 1, scroll, width);
                for (y, line) in lines.iter().enumerate() {
                    let last = line.chars().last().expect("a rendered line");
                    let expected = match y {
                        0 => border.top_right,
                        9 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(
                        last.to_string(),
                        expected,
                        "right border eaten at width {width}, scroll {scroll}, row {y}: {line}"
                    );
                }
            }
        }
        // What the pan is for: text that the column cut off at rest becomes readable further along.
        let head = render_table(&resources, 1, 0, 140)[3].clone();
        let panned = render_table(&resources, 1, 60, 140)[3].clone();
        assert!(head.contains("Kustomize build failed"), "{head}");
        assert!(!head.contains("evalsymlink"), "the tail is cut off at rest: {head}");
        assert!(panned.contains("evalsymlink"), "the pan reveals it: {panned}");
    }

    fn node(collapsed: bool, failed: usize, reconciling: usize) -> FlatTreeNode {
        FlatTreeNode {
            idx: 0,
            depth: 1,
            has_children: true,
            collapsed,
            hidden_failed: failed,
            hidden_reconciling: reconciling,
        }
    }

    #[test]
    fn a_fold_announces_the_problems_it_hides_and_stays_silent_otherwise() {
        assert_eq!(hidden_badge(&node(true, 2, 1)), "  ✗2  ↻1");
        assert_eq!(hidden_badge(&node(true, 0, 3)), "  ↻3");
        // A branch folded over healthy resources has nothing to announce.
        assert_eq!(hidden_badge(&node(true, 0, 0)), "");
        // An expanded node carries no tally: what it holds is on screen already.
        assert_eq!(hidden_badge(&node(false, 0, 0)), "");
    }

    #[test]
    fn the_hidden_badge_is_split_off_a_label_full_of_multibyte_glyphs() {
        // The label is sliced on a byte index, and the tree markers are three bytes each: a naive
        // count would cut one in half and panic.
        let n = node(true, 1, 0);
        let label = format!("  ▸ Kustomization apps  ⊞{}", hidden_badge(&n));
        let line = labelled_row(&label, &n);
        assert_eq!(line.spans.len(), 2);
        assert_eq!(line.spans[0].content, "  ▸ Kustomization apps  ⊞");
        assert_eq!(line.spans[1].content, "  ✗1");
        assert_eq!(line.spans[1].style.fg, Some(Color::Red));
        // No tally, no split: one plain span.
        let plain = labelled_row("  ▾ HelmRelease app", &node(false, 0, 0));
        assert_eq!(plain.spans.len(), 1);
    }

    #[test]
    fn a_reconciling_fold_is_cyan_and_a_failing_one_red() {
        assert_eq!(
            labelled_row(&format!("x{}", hidden_badge(&node(true, 0, 2))), &node(true, 0, 2)).spans[1].style.fg,
            Some(Color::Cyan)
        );
        // A failure outranks a reconcile in flight: it is the one worth walking to.
        assert_eq!(
            labelled_row(&format!("x{}", hidden_badge(&node(true, 1, 2))), &node(true, 1, 2)).spans[1].style.fg,
            Some(Color::Red)
        );
    }

    fn render_tree(
        view: &[TreeRow],
        resources: &[FluxResource],
        selected: usize,
        msg_scroll: usize,
        width: u16,
    ) -> Vec<String> {
        use ratatui::backend::TestBackend;
        use ratatui::Terminal;
        const H: u16 = 10;
        let expanded = std::collections::HashMap::new();
        let (rows, widths, _) =
            flux_tree_table_parts(view, resources, &expanded, Some(selected), msg_scroll, width);
        let mut state = TableState::default();
        state.select(Some(selected));
        let mut terminal = Terminal::new(TestBackend::new(width, H)).expect("test terminal");
        terminal
            .draw(|f| {
                let t = Table::new(rows, widths)
                    .header(flux_tree_header_row())
                    .block(Block::default().borders(Borders::ALL).title("flux tree"))
                    .row_highlight_style(Style::default().bg(SELECTED_BG))
                    .highlight_symbol("> ");
                f.render_stateful_widget(t, f.area(), &mut state);
            })
            .expect("draw");
        let buffer = terminal.backend().buffer().clone();
        (0..H)
            .map(|y| {
                (0..width)
                    .map(|x| buffer.cell((x, y)).expect("cell").symbol().to_string())
                    .collect::<String>()
            })
            .collect()
    }

    // A deep tree whose deepest row carries both the inventory marker and a hidden-problem tally:
    // the widest RESOURCE label the column has to size itself on.
    fn deep_tree_set() -> (Vec<TreeRow>, Vec<FluxResource>) {
        let mut resources = Vec::new();
        let mut view = Vec::new();
        for depth in 0..6 {
            let mut r = res("Kustomization", Some(false), false);
            r.name = format!("a-rather-long-kustomization-name-{depth}");
            if depth == 5 {
                r.ready = FluxReady::Failed;
                r.message = "Kustomize build failed: evalsymlink failure on \
                    '/tmp/kustomization-1234/base/app' : lstat: no such file".to_string();
            }
            resources.push(r);
            view.push(TreeRow::Res(FlatTreeNode {
                idx: depth,
                depth,
                has_children: depth < 5,
                collapsed: depth == 4,
                hidden_failed: if depth == 4 { 3 } else { 0 },
                hidden_reconciling: if depth == 4 { 12 } else { 0 },
            }));
        }
        (view, resources)
    }

    #[test]
    fn the_tree_keeps_its_right_border_at_every_width() {
        let (view, resources) = deep_tree_set();
        let border = ratatui::symbols::border::PLAIN;
        for width in [60_u16, 80, 100, 140, 196] {
            for scroll in [0_usize, 30, 400] {
                for selected in [0_usize, 4, 5] {
                    let lines = render_tree(&view, &resources, selected, scroll, width);
                    for (y, line) in lines.iter().enumerate() {
                        let last = line.chars().last().expect("a rendered line");
                        let expected = match y {
                            0 => border.top_right,
                            9 => border.bottom_right,
                            _ => border.vertical_right,
                        };
                        assert_eq!(
                            last.to_string(),
                            expected,
                            "right border eaten at width {width}, scroll {scroll}, row {selected}, line {y}: {line}"
                        );
                    }
                }
            }
        }
    }

    #[test]
    fn a_folded_branch_shows_its_tally_on_screen() {
        let (view, resources) = deep_tree_set();
        let lines = render_tree(&view, &resources, 0, 0, 196);
        // Header on row 1, then one line per node: the folded one is the fifth.
        let folded = &lines[6];
        assert!(folded.contains("✗3"), "the failures under the fold are announced: {folded}");
        assert!(folded.contains("↻12"), "so are the reconciles in flight: {folded}");
    }

    #[test]
    fn the_badge_keeps_its_style_in_the_window_and_pans_out_of_it() {
        let r = res("Kustomization", Some(false), false);
        let line = flux_message_line(&r, Color::White);

        let head = line_window(&line, 0, 40);
        assert_eq!(head.spans[0].content, NO_PRUNE_BADGE);
        assert_eq!(head.spans[0].style, no_prune_badge_style());

        // Panned past the badge, what is left is the message alone — the badge is text like the
        // rest, not a pinned prefix.
        let panned = win_text(&line_window(&line, NO_PRUNE_BADGE.chars().count(), 40));
        assert!(panned.starts_with('…'));
        assert!(!panned.contains("no-prune"));
        assert!(panned.contains("Applied revision"));
    }

    #[test]
    fn the_suspend_key_names_the_direction_it_would_take() {
        let st = lang::t(AiLanguage::En);
        let running = synthetic_flux_record(&res("HelmRelease", None, false));
        let suspended = synthetic_flux_record(&res("HelmRelease", None, true));
        assert_eq!(suspend_key_label(Some(&running), st), st.k_suspend);
        assert_eq!(suspend_key_label(Some(&suspended), st), st.k_resume);
        // No row under the cursor: the key still exists, and it suspends.
        assert_eq!(suspend_key_label(None, st), st.k_suspend);
    }
}

#[cfg(test)]
mod footer_tests {
    use super::*;

    fn key(k: &str) -> Span<'static> {
        Span::styled(format!(" {} ", k), Style::default().fg(Color::Black).bg(Color::White))
    }
    fn lbl(l: &str) -> Span<'static> {
        Span::raw(format!(" {}   ", l))
    }
    fn row_text(groups: &[FooterGroup]) -> String {
        render_footer_row(groups).iter().map(|s| s.content.to_string()).collect()
    }

    // The events footer, as built by draw(): entry keys, a/w/e filters, navigation, view, tools.
    fn selection_footer() -> (Vec<Span<'static>>, Vec<Span<'static>>) {
        let spans = vec![
            key("q"), lbl("quitter"),
            key(":"), lbl("commandes"),
            key("Esc"), lbl("retour"),
            footer_sep(),
            key("a"), lbl("tous"),
            key("w"), lbl("warnings"),
            key("e"), lbl("erreurs"),
            footer_sep(),
            key("↑↓"), lbl("navigation"),
            key("Shift+↑↓"), lbl("défilement détail"),
            key("s"), lbl("figer"),
            footer_sep(),
            key("Enter"), lbl("zoom"),
            key("Tab"), lbl("vue"),
            footer_sep(),
            key("D"), lbl("diagnostic"),
            key("X"), lbl("extraire"),
        ];
        let tools = vec![
            key("c"), lbl("copier"),
            key("i"), lbl("IA"),
            key("L"), lbl("langue:fr"),
            key("m"), lbl("modèle:local"),
        ];
        (spans, tools)
    }

    fn layout(width: usize) -> (String, String) {
        let (spans, tools) = selection_footer();
        let groups = footer_groups(spans);
        let tools = footer_groups(tools).into_iter().flatten().collect::<FooterGroup>();
        let (top, bottom) = balance_footer_rows(groups, tools, width);
        (row_text(&top), row_text(&bottom))
    }

    #[test]
    fn groups_are_never_split_across_rows() {
        let (top, bottom) = layout(140);
        // The three event filters belong to the same group: same row, and side by side.
        let row = if top.contains(" a ") { &top } else { &bottom };
        let a = row.find(" a ").expect("filter a on that row");
        let w = row.find(" w ").expect("filter w on the same row");
        let e = row.find(" e ").expect("filter e on the same row");
        assert!(a < w && w < e, "a/w/e out of order: {row}");
        assert!(!row[a..e].contains('│'), "a/w/e split by a divider: {row}");
    }

    #[test]
    fn entry_keys_open_the_top_row_and_tools_close_the_bottom_one() {
        let (top, bottom) = layout(140);
        assert!(top.starts_with(" q "), "top row should start with the entry group: {top}");
        assert!(bottom.trim_end().ends_with("modèle:local"), "tool bar should close the footer: {bottom}");
    }

    #[test]
    fn rows_stay_balanced() {
        let (top, bottom) = layout(140);
        let (t, b) = (top.chars().count(), bottom.chars().count());
        assert!(t.abs_diff(b) < 20, "unbalanced rows: {t} vs {b}");
    }

    #[test]
    fn everything_fits_on_one_row_when_wide_enough() {
        let (top, bottom) = layout(400);
        assert!(bottom.is_empty(), "second row should stay empty: {bottom}");
        assert!(top.contains("modèle:local"), "tool bar should join the single row: {top}");
    }
}

#[cfg(test)]
mod wrapped_panel_rows_tests {
    use super::*;

    #[test]
    fn a_padded_key_column_counts_its_spaces() {
        // The line the node panel is made of: a key padded to a fixed column, then its value. On its
        // words alone it fits one row — with the padding it takes two, and the panel scrolled on the
        // short count would keep its last block below the frame.
        let text = format!("  {:<44} = {}", "rke2.io/node-config-hash", "U".repeat(56));
        let lines = vec![Line::from(text.clone())];
        assert_eq!(wrapped_rows(&Line::from(text), 98), 1, "the word-only measure misses the padding");
        assert_eq!(wrapped_panel_rows(&lines, 98), 2);
        assert_eq!(wrapped_panel_rows(&lines, 198), 1);
    }
}

#[cfg(test)]
mod rbac_scope_tests {
    use super::*;
    use crate::rbac::{Provenance, RoleKind, Scope, Subject};

    fn subject(kind: &str, ns: Option<&str>, name: &str) -> Subject {
        Subject {
            kind: kind.to_string(),
            name: name.to_string(),
            namespace: ns.map(str::to_string),
        }
    }

    fn binding(kind: &str, scope: Scope, subjects: Vec<Subject>, role: usize) -> RbacBinding {
        RbacBinding {
            scope,
            binding_kind: kind.to_string(),
            binding_name: "b".to_string(),
            subjects,
            role_ref: crate::rbac::RoleRef { kind: "ClusterRole".to_string(), name: "admin".to_string() },
            rules: Vec::new(),
            via_clusterrole: true,
            aggregated: false,
            provenance: Provenance::Unmanaged,
            source: None,
            severity: RbacSeverity::Info,
            findings: Vec::new(),
            age: "1d".to_string(),
            role_idx: Some(role),
            sa_idx: Vec::new(),
        }
    }

    fn role(kind: RoleKind, ns: &str, name: &str) -> RoleEntry {
        RoleEntry {
            kind,
            namespace: ns.to_string(),
            name: name.to_string(),
            rules: Vec::new(),
            own_rules: 0,
            aggregated: false,
            aggregates: Vec::new(),
            aggregates_into: Vec::new(),
            aggregation_partial: false,
            bound_cluster: 0,
            bound_namespaces: Vec::new(),
            provenance: Provenance::Unmanaged,
            source: None,
            age: "1d".to_string(),
            severity: RbacSeverity::Info,
            findings: Vec::new(),
        }
    }

    // The two ways a binding belongs to a namespace: it grants there, or it grants to an account
    // that lives there. A cluster-wide grant to someone else's ServiceAccount is neither.
    #[test]
    fn a_namespace_owns_what_grants_in_it_and_what_grants_to_it() {
        let ns = "blanche-prd";

        let local = binding(
            "RoleBinding",
            Scope::Namespace(ns.to_string()),
            vec![subject("User", None, "alice")],
            0,
        );
        assert!(rbac_binding_in_ns(&local, ns));

        // The one that matters most: this namespace's account, bound cluster-wide.
        let escalation = binding(
            "ClusterRoleBinding",
            Scope::ClusterWide,
            vec![subject("ServiceAccount", Some(ns), "runner")],
            0,
        );
        assert!(rbac_binding_in_ns(&escalation, ns));

        let elsewhere = binding(
            "RoleBinding",
            Scope::Namespace("kube-system".to_string()),
            vec![subject("ServiceAccount", Some("kube-system"), "coredns")],
            0,
        );
        assert!(!rbac_binding_in_ns(&elsewhere, ns));

        // Cluster-wide, to accounts of another namespace: it applies here as it does everywhere,
        // and listing it would bury the rows that are about this namespace.
        let ambient = binding(
            "ClusterRoleBinding",
            Scope::ClusterWide,
            vec![subject("Group", None, "system:masters")],
            0,
        );
        assert!(!rbac_binding_in_ns(&ambient, ns));
    }

    // A ClusterRole is cluster-scoped as an object, but it is part of a namespace's RBAC as soon as
    // a binding in scope grants it — and a Role of the namespace stays in scope with no binding at
    // all, because an unbound Role there is still that namespace's standing offer.
    #[test]
    fn a_role_is_in_scope_through_the_namespace_or_through_a_binding() {
        let ns = "blanche-prd";
        let bindings = vec![binding(
            "RoleBinding",
            Scope::Namespace(ns.to_string()),
            vec![subject("User", None, "alice")],
            1,
        )];
        let reached = rbac_roles_reached_in_ns(&bindings, ns);
        assert_eq!(reached.len(), 1);

        let granted = role(RoleKind::ClusterRole, "", "admin");
        assert!(rbac_role_in_ns(&granted, 1, &reached, ns));

        let unbound_here = role(RoleKind::Role, ns, "leader-election");
        assert!(rbac_role_in_ns(&unbound_here, 7, &reached, ns));

        let unrelated = role(RoleKind::ClusterRole, "", "view");
        assert!(!rbac_role_in_ns(&unrelated, 9, &reached, ns));

        let other_ns = role(RoleKind::Role, "kube-system", "extension-apiserver");
        assert!(!rbac_role_in_ns(&other_ns, 11, &reached, ns));
    }
}

// The detail panel is where the risk is read in full, now that the table's RISK column holds one
// tag. Its findings block is a table drawn with padding, so the two ways padding fails — a value
// wider than its column, and a line wider than the frame — are what these check.
#[cfg(test)]
mod rbac_detail_tests {
    use super::*;
    use crate::rbac::Finding;
    use ratatui::{backend::TestBackend, Terminal};

    fn findings() -> Vec<Finding> {
        vec![
            Finding {
                sev: RbacSeverity::Critical,
                tag: "impersonate",
                detail: "impersonate verb — can become any user/group/SA".to_string(),
            },
            Finding {
                sev: RbacSeverity::Info,
                tag: "inert-cluster-rules",
                detail: "cluster-scoped rules inert in this namespace: namespaces,                          customresourcedefinitions, persistentvolumes, storageclasses"
                    .to_string(),
            },
        ]
    }

    fn text(lines: &[Line<'static>]) -> String {
        lines
            .iter()
            .map(|l| l.spans.iter().map(|s| s.content.clone()).collect::<String>())
            .collect::<Vec<_>>()
            .join("\n")
    }

    #[test]
    fn the_longest_tag_still_gets_a_gap_before_its_explanation() {
        let joined = text(&rbac_findings_block(&findings()));
        assert!(
            joined.contains("inert-cluster-rules  cluster-scoped"),
            "a tag as wide as its column must not glue itself to the detail: {joined}"
        );
        assert!(joined.contains("impersonate          impersonate verb"), "{joined}");
        assert!(joined.contains("SEV"), "the block reads as a table: {joined}");
    }

    #[test]
    fn no_findings_draws_no_header() {
        assert!(rbac_findings_block(&[]).is_empty());
    }

    // `aggregated` is exactly as wide as the key column: padding alone would glue it to its value.
    #[test]
    fn a_label_as_wide_as_its_column_keeps_a_space() {
        let line = rbac_detail_label("aggregated", "rules composed by aggregation".to_string());
        assert!(text(&[line]).starts_with("aggregated rules composed"));
        let short = rbac_detail_label("scope", "ns:app".to_string());
        assert_eq!(text(&[short]), "scope     ns:app");
    }

    #[test]
    fn the_right_border_survives_every_width() {
        let lines = rbac_findings_block(&findings());
        let border = ratatui::symbols::border::PLAIN;
        for width in [40_u16, 60, 100, 196] {
            let mut terminal = Terminal::new(TestBackend::new(width, 20)).expect("test terminal");
            terminal
                .draw(|f| {
                    // Same as the view: the detail panel clips and pans, it never wraps.
                    let p = Paragraph::new(lines.clone())
                        .block(Block::default().borders(Borders::ALL).title(" rbac "));
                    f.render_widget(p, f.area());
                })
                .expect("draw");
            let buffer = terminal.backend().buffer().clone();
            for y in 0..20 {
                let cell = buffer.cell((width - 1, y)).expect("right column");
                let expected = match y {
                    0 => border.top_right,
                    19 => border.bottom_right,
                    _ => border.vertical_right,
                };
                assert_eq!(cell.symbol(), expected, "right border eaten at width {width}, row {y}");
            }
        }
    }
}

#[cfg(test)]
mod palette_overlay_tests {
    use super::*;

    // The palette is drawn over the view it was opened from. Every view that binds `:` must answer
    // itself here: a mode missing from this resolution is drawn as the event table instead, which is
    // exactly what the Rancher view did.
    #[test]
    fn the_palette_keeps_drawing_the_view_it_was_opened_from() {
        for mode in [
            Mode::Selection,
            Mode::Nodes,
            Mode::Flux,
            Mode::Pods,
            Mode::Rbac,
            Mode::Vuln,
            Mode::Secrets,
            Mode::Certs,
            Mode::Kyverno,
            Mode::Reflector,
            Mode::Velero,
            Mode::K8ssandra,
            Mode::Configmaps,
            Mode::Namespaces,
            Mode::Services,
            Mode::Storage,
            Mode::Capacity,
            Mode::Rancher,
            Mode::RancherFull,
            Mode::Argo,
            Mode::ArgoFull,
            Mode::Identity,
            Mode::IdentityFull,
        ] {
            assert_eq!(palette_base_mode(mode), mode, "{mode:?} drawn as another view");
        }
        // The overlays have no layout of their own to fall back on.
        assert_eq!(palette_base_mode(Mode::AiPanel), Mode::Selection);
        assert_eq!(palette_base_mode(Mode::Diagnostic), Mode::Selection);
    }
}

#[cfg(test)]
mod identity_view_tests {
    use super::*;
    use crate::identity::{BindingRef, CredentialFacts};
    use ratatui::backend::TestBackend;
    use ratatui::Terminal;

    // A row shaped like the ones a real cluster produces: a long name, a long address, several
    // groups — everything that competes for the width the border needs.
    fn user() -> IdentUser {
        IdentUser {
            name: "alice-martin.consultant".to_string(),
            email: "alice.martin@a-rather-long-domain.example.com".to_string(),
            display_name: "Alice Martin".to_string(),
            disabled: false,
            phase: Phase::Locked,
            raw_phase: "Active".to_string(),
            member_of: vec![
                "lecteurs".to_string(),
                "ops".to_string(),
                "plateforme-astreinte".to_string(),
            ],
            invitation: Invitation::Expired { expires: 1_756_000_000 },
            creds: Some(CredentialFacts {
                invite_expires: Some(1_756_000_000),
                locked_until: Some(1_900_000_000),
                failed_attempts: 7,
            }),
            age: "142d".to_string(),
            hints: vec![
                crate::identity::Hint {
                    level: crate::identity::HintLevel::Warn,
                    text: "verrouillé après 7 échecs, et une phrase assez longue pour se replier \
                           plusieurs fois dans un panneau étroit"
                        .to_string(),
                },
            ],
            uid: "ident|user|alice".to_string(),
        }
    }

    fn group() -> IdentGroup {
        IdentGroup {
            name: "plateforme-astreinte".to_string(),
            subject: "kdt:plateforme-astreinte".to_string(),
            description: "astreinte plateforme, lecture seule hors incident".to_string(),
            members: vec!["alice-martin.consultant".to_string(), "fantome".to_string()],
            resolved: vec!["alice-martin.consultant".to_string()],
            unknown: vec!["fantome".to_string()],
            bindings: vec![BindingRef {
                kind: "ClusterRoleBinding".to_string(),
                namespace: String::new(),
                name: "kdt-plateforme-astreinte-view".to_string(),
                role: "ClusterRole/view".to_string(),
            }],
            age: "89d".to_string(),
            hints: vec![crate::identity::Hint {
                level: crate::identity::HintLevel::Warn,
                text: "members sans compte : fantome".to_string(),
            }],
            uid: "ident|group|plateforme".to_string(),
        }
    }

    fn rows() -> Vec<(IdentWorld, Vec<IdentRow>)> {
        vec![
            (IdentWorld::Users, vec![IdentRow::User(Box::new(user()))]),
            (IdentWorld::Groups, vec![IdentRow::Group(Box::new(group()))]),
        ]
    }

    #[test]
    fn the_right_border_survives_every_width_in_both_worlds() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let border = ratatui::symbols::border::PLAIN;
        for (world, src) in rows() {
            for width in [40_u16, 60, 100, 196] {
                let mut terminal =
                    Terminal::new(TestBackend::new(width, 12)).expect("test terminal");
                terminal
                    .draw(|f| {
                        let (header, rows, widths) = ident_table_parts(world, &src, st);
                        let table = Table::new(rows, widths)
                            .header(header)
                            .block(Block::default().borders(Borders::ALL).title(" identity "))
                            .highlight_symbol("> ");
                        f.render_widget(table, f.area());
                    })
                    .expect("draw");
                let buffer = terminal.backend().buffer().clone();
                for y in 0..12 {
                    let cell = buffer.cell((width - 1, y)).expect("right column");
                    let expected = match y {
                        0 => border.top_right,
                        11 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(
                        cell.symbol(),
                        expected,
                        "right border eaten at width {width}, row {y}, world {world:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn the_detail_panel_keeps_its_frame_at_every_width() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let border = ratatui::symbols::border::PLAIN;
        for (_, src) in rows() {
            let row = src.into_iter().next().expect("one row");
            for width in [40_u16, 60, 100, 196] {
                let mut terminal =
                    Terminal::new(TestBackend::new(width, 24)).expect("test terminal");
                let (title, lines) = ident_detail_lines(&row, st, width.saturating_sub(2) as usize);
                terminal
                    .draw(|f| {
                        let p = Paragraph::new(lines.clone())
                            .wrap(Wrap { trim: false })
                            .block(
                                Block::default()
                                    .borders(Borders::ALL)
                                    .title(title.clone()),
                            );
                        f.render_widget(p, f.area());
                    })
                    .expect("draw");
                let buffer = terminal.backend().buffer().clone();
                for y in 0..24 {
                    let cell = buffer.cell((width - 1, y)).expect("right column");
                    let expected = match y {
                        0 => border.top_right,
                        23 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(cell.symbol(), expected, "frame eaten at width {width}, row {y}");
                }
            }
        }
    }

    // The whole point of showing `Locked`: the controller never writes it, so the panel has to keep
    // the phase the CRD *does* carry next to it rather than replacing it silently.
    #[test]
    fn the_detail_panel_shows_the_controllers_own_phase_beside_kdts() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let row = IdentRow::User(Box::new(user()));
        let (_, lines) = ident_detail_lines(&row, st, 100);
        let text: String = lines.iter().map(|l| l.to_string()).collect::<Vec<_>>().join("\n");
        assert!(text.contains("status.phase"), "the CRD's own phase is not shown: {text}");
        assert!(text.contains("Active"));
        // And the subject, which is what a binding has to reference.
        assert!(text.contains("kdt:alice-martin.consultant"));
    }

    // A group with no binding grants nothing. The panel has to say so in words, because a blank
    // line reads as "nothing to report" — which is the opposite of the truth.
    #[test]
    fn a_group_with_no_binding_says_so_rather_than_leaving_the_line_blank() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let bare = IdentGroup { bindings: Vec::new(), ..group() };
        let (_, lines) = ident_detail_lines(&IdentRow::Group(Box::new(bare)), st, 100);
        let text: String = lines.iter().map(|l| l.to_string()).collect::<Vec<_>>().join("\n");
        assert!(text.contains(st.ident_none), "an unbound group renders as blank: {text}");
    }

    // The form's own refusals, and only those: everything else is the apiserver's to say.
    #[test]
    fn the_form_refuses_only_what_it_can_rule_out_by_itself() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let mut form = IdentFormView::new(IdentFormKind::User);
        assert!(form.validate(st).is_err());
        form.name = "alice".to_string();
        assert!(form.validate(st).is_err(), "a user with no email must not be sent");
        form.email = "alice@example.com".to_string();
        assert!(form.validate(st).is_ok());
        // A name kdt has no business judging goes to the apiserver, which owns the rules.
        form.name = "Alice_Martin".to_string();
        assert!(form.validate(st).is_ok());
        // A group needs a name and nothing else.
        let mut g = IdentFormView::new(IdentFormKind::Group);
        assert!(g.validate(st).is_err());
        g.name = "ops".to_string();
        assert!(g.validate(st).is_ok());
    }

    // The picker writes on the group either way round, and carries the index a removal needs.
    #[test]
    fn the_picker_writes_on_the_group_from_whichever_side_it_was_opened() {
        let from_user = IdentPickView {
            anchor: "alice".to_string(),
            from_user: true,
            items: vec![("ops".to_string(), false, 0)],
            cursor: 0,
            error: None,
        };
        match from_user.toggle() {
            Some(IdentityWrite::AddMember { group, user }) => {
                assert_eq!(group, "ops");
                assert_eq!(user, "alice");
            }
            other => panic!("expected an add on the group, got {other:?}"),
        }

        let from_group = IdentPickView {
            anchor: "ops".to_string(),
            from_user: false,
            items: vec![("alice".to_string(), true, 3)],
            cursor: 0,
            error: None,
        };
        match from_group.toggle() {
            Some(IdentityWrite::RemoveMember { group, user, index }) => {
                assert_eq!(group, "ops");
                assert_eq!(user, "alice");
                assert_eq!(index, 3, "the index the guarded patch tests against is lost");
            }
            other => panic!("expected a removal on the group, got {other:?}"),
        }
    }

    // Only the invitation opens the entry prefilled: an empty box that expects `72h` is how one
    // asks for three days and gets seventy-two seconds.
    #[test]
    fn the_validity_entry_opens_on_the_value_the_server_itself_defaults_to() {
        assert!(menu_action_takes_input(Some(&MenuAction::IdentInviteUser)));
        assert!(menu_action_free_text(Some(&MenuAction::IdentInviteUser)));
        assert_eq!(DEFAULT_VALIDITY, "72h");
    }
}

#[cfg(test)]
mod rancher_view_tests {
    use super::*;
    use crate::rancher::RancherProject;

    fn project() -> RancherProject {
        RancherProject {
            uid: "ranch|project|c-m-abc:p-dfg12".to_string(),
            id: "p-dfg12".to_string(),
            display_name: "datasmart".to_string(),
            cluster: "c-m-abc".to_string(),
            namespaces: vec!["blanche-prd".to_string()],
            members: 3,
            namespace: "c-m-abc".to_string(),
            name: "p-dfg12".to_string(),
            ..RancherProject::default()
        }
    }

    // `h` writes, so the row has to name an object that exists here. A project rebuilt from the
    // namespace annotations of a downstream cluster names none: the `Project` is upstream.
    #[test]
    fn only_a_project_this_cluster_holds_names_an_object_to_touch() {
        let local = ranch_project_record(&project());
        assert_eq!(local.kind, "Project");
        assert_eq!(local.namespace, "c-m-abc");
        assert_eq!(local.name, "p-dfg12");

        let upstream = ranch_project_record(&RancherProject {
            namespace: String::new(),
            ..project()
        });
        assert!(upstream.kind.is_empty(), "kind: {}", upstream.kind);
        // The row still reads as a project — only the write target is gone.
        assert!(upstream.message.contains("datasmart"));
    }
}

#[cfg(test)]
mod argo_view_tests {
    use super::*;
    use crate::argocd::{
        ArgoApp, ArgoAppSet, ArgoCondition, ArgoEndpoint, ArgoProject, ArgoResource, ArgoRole,
        ArgoSource, EndpointKind,
    };
    use ratatui::backend::TestBackend;
    use ratatui::Terminal;

    // The row read off a real cluster: a comparison that failed on a git credential, and a health
    // left over from before it did.
    fn blind_app() -> ArgoApp {
        ArgoApp {
            namespace: "argocd-prd".to_string(),
            name: "application-dsm-blanche-pprd-it".to_string(),
            project: "application-dsm-blanche".to_string(),
            sync: "Unknown".to_string(),
            health: "Healthy".to_string(),
            dest_label: "dsm-staging".to_string(),
            dest_namespace: "blanche-pprd".to_string(),
            dest_server: "https://dsm-staging.privatelink.northeurope.azmk8s.io:443".to_string(),
            sources: vec![ArgoSource {
                repo_url: "https://gitlab.example.com/group/subgroup/a-very-long-chart-name.git"
                    .to_string(),
                path: "chart".to_string(),
                target_revision: "main".to_string(),
                ..ArgoSource::default()
            }],
            revision: "4097485".to_string(),
            revision_full: "4097485d00206a5fb6ce11b7a3c8c6f3c294f770".to_string(),
            op_phase: "Failed".to_string(),
            op_age: "5d".to_string(),
            op_message: "one or more objects failed to apply, reason: secrets is forbidden \
                         and the message keeps going well past any column width"
                .to_string(),
            conditions: vec![ArgoCondition {
                kind: "ComparisonError".to_string(),
                message: "failed to list refs: authentication required".to_string(),
                ..ArgoCondition::default()
            }],
            resources: vec![ArgoResource {
                kind: "Deployment".to_string(),
                group: "apps".to_string(),
                namespace: "blanche-pprd".to_string(),
                name: "blanche".to_string(),
                sync: "OutOfSync".to_string(),
                health: "Missing".to_string(),
                requires_pruning: false,
            }],
            out_of_sync: 1,
            reconciled_age: "2h".to_string(),
            age: "142d".to_string(),
            hints: vec![
                crate::argocd::Hint {
                    level: crate::argocd::HintLevel::Danger,
                    text: "ComparisonError : failed to list refs: authentication required, and a \
                           message long enough to wrap several times over in a narrow panel"
                        .to_string(),
                },
                crate::argocd::Hint {
                    level: crate::argocd::HintLevel::Warn,
                    text: "health Healthy predates the comparison error.".to_string(),
                },
            ],
            uid: "argo|app|argocd-prd/blanche".to_string(),
            ..ArgoApp::default()
        }
    }

    fn set() -> ArgoAppSet {
        ArgoAppSet {
            namespace: "argocd-prd".to_string(),
            name: "tenants".to_string(),
            generators: vec!["git".to_string(), "clusters".to_string()],
            apps: vec!["tenant-a".to_string(), "tenant-b".to_string()],
            apps_out_of_sync: 1,
            conditions: vec![ArgoCondition {
                kind: "ErrorOccurred".to_string(),
                status: "True".to_string(),
                reason: "ApplicationGenerationFromParamsError".to_string(),
                message: "error generating params from git".to_string(),
            }],
            age: "30d".to_string(),
            ..ArgoAppSet::default()
        }
    }

    fn project() -> ArgoProject {
        ArgoProject {
            namespace: "argocd-prd".to_string(),
            name: "dsm-webtools".to_string(),
            description: "AppProject for dsm-webtools, with a description long enough to fill the \
                          slack column and then some"
                .to_string(),
            source_repos: vec!["*".to_string()],
            destinations: vec!["dsm-staging/dsm-webtools-dev".to_string()],
            open_sources: true,
            roles: vec![ArgoRole {
                name: "project-operators".to_string(),
                groups: vec!["FR-Rule-MSE-DATASMART-techleads".to_string()],
                policies: 22,
                writes: true,
            }],
            apps: 4,
            apps_out_of_sync: 1,
            age: "76d".to_string(),
            ..ArgoProject::default()
        }
    }

    fn endpoint() -> ArgoEndpoint {
        ArgoEndpoint {
            kind: EndpointKind::Cluster,
            namespace: "argocd-prd".to_string(),
            secret: "cluster-dsm-staging".to_string(),
            url: "https://dsm-staging-hs-neu-aks.privatelink.northeurope.azmk8s.io:443".to_string(),
            label: "dsm-staging".to_string(),
            auth: "bearer token".to_string(),
            namespaces: vec!["a".to_string(), "b".to_string()],
            used_by: 12,
            age: "160d".to_string(),
            ..ArgoEndpoint::default()
        }
    }

    fn rows() -> Vec<(ArgoWorld, Vec<ArgoRow>)> {
        vec![
            (ArgoWorld::Apps, vec![ArgoRow::App(Box::new(blind_app()))]),
            (ArgoWorld::Sets, vec![ArgoRow::Set(Box::new(set()))]),
            (ArgoWorld::Projects, vec![ArgoRow::Project(Box::new(project()))]),
            (ArgoWorld::Repos, vec![ArgoRow::Endpoint(Box::new(endpoint()))]),
        ]
    }

    // A stale `Healthy` must never be painted green: that colour is the whole reason the row is
    // misread in the Argo CD UI in the first place.
    #[test]
    fn a_health_computed_before_the_comparison_broke_is_not_green() {
        let a = blind_app();
        assert_eq!(argo_health_style(&a).fg, Some(DIM));
        let sound = ArgoApp { sync: "Synced".to_string(), conditions: Vec::new(), ..a };
        assert_eq!(argo_health_style(&sound).fg, Some(Color::Green));
    }

    #[test]
    fn the_right_border_survives_every_width_in_all_four_worlds() {
        let border = ratatui::symbols::border::PLAIN;
        for (world, src) in rows() {
            for width in [40_u16, 60, 100, 196] {
                let mut terminal =
                    Terminal::new(TestBackend::new(width, 12)).expect("test terminal");
                terminal
                    .draw(|f| {
                        let (header, rows, widths) = argo_table_parts(world, &src, width);
                        let table = Table::new(rows, widths)
                            .header(header)
                            .block(Block::default().borders(Borders::ALL).title(" argocd "))
                            .highlight_symbol("> ");
                        f.render_widget(table, f.area());
                    })
                    .expect("draw");
                let buffer = terminal.backend().buffer().clone();
                for y in 0..12 {
                    let cell = buffer.cell((width - 1, y)).expect("right column");
                    let expected = match y {
                        0 => border.top_right,
                        11 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(
                        cell.symbol(),
                        expected,
                        "right border eaten at width {width}, row {y}, world {world:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn the_detail_panel_keeps_its_frame_at_every_width() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let border = ratatui::symbols::border::PLAIN;
        for (_, src) in rows() {
            let row = src.into_iter().next().expect("one row");
            for width in [40_u16, 60, 100, 196] {
                let mut terminal =
                    Terminal::new(TestBackend::new(width, 24)).expect("test terminal");
                let (title, lines) = argo_detail_lines(&row, st, width.saturating_sub(2) as usize);
                terminal
                    .draw(|f| {
                        let p = Paragraph::new(lines.clone())
                            .wrap(Wrap { trim: false })
                            .block(Block::default().borders(Borders::ALL).title(title.clone()));
                        f.render_widget(p, f.area());
                    })
                    .expect("draw");
                let buffer = terminal.backend().buffer().clone();
                for y in 0..24 {
                    let cell = buffer.cell((width - 1, y)).expect("right column");
                    let expected = match y {
                        0 => border.top_right,
                        23 => border.bottom_right,
                        _ => border.vertical_right,
                    };
                    assert_eq!(
                        cell.symbol(),
                        expected,
                        "right border eaten at width {width}, row {y}"
                    );
                }
            }
        }
    }

    // The panel is anchored on its own height: counting raw lines would leave the diagnostic block
    // — the last one, and the reason the panel is open — below the frame as soon as a hint wraps.
    #[test]
    fn the_wrapped_height_of_the_panel_exceeds_its_line_count() {
        let st = lang::t(crate::ai::AiLanguage::Fr);
        let row = ArgoRow::App(Box::new(blind_app()));
        let (_, lines) = argo_detail_lines(&row, st, 58);
        assert!(
            wrapped_panel_rows(&lines, 58) > lines.len(),
            "a panel whose hints wrap is taller than its line count"
        );
    }
}
